// Full text of the Statute, Rules and Charter (extracted from the official .docx files)
export const DOC_TEXT = {"nizom": [{"y": "heading","x": "ЎЗБЕКИСТОН ХАЛҚАРО АРБИТРАЖ СУДЛАРИ БИРЛАШМАСИ"},{"y": "heading","x": "ҲУЗУРИДАГИ ХАЛҚАРО  АРБИТРАЖ СУДИНИНГ"},{"y": "heading","x": "НИЗОМИ"},{"y": "para","x": "Тошкент-2026"},{"y": "chapter","x": "I БОБ. УМУМИЙ ҚОИДАЛАР"},{"y": "article","x": "1-модда. Ушбу Низомнинг мақсади ва ҳуқуқий асослари"},{"y": "para","x": "1.1. Мазкур Низом Ўзбекистон Халқаро Арбитраж Судлари Бирлашмаси ҳузуридаги Халқаро арбитраж судининг ҳуқуқий мақомини, ташкилий тузилишини, бошқарув тизимини, ваколатларини, фаолият тамойилларини ҳамда иш юритишнинг умумий қоидаларини белгилайди."},{"y": "para","x": "1.2. Халқаро арбитраж суди доимий фаолият юритувчи мустақил арбитраж муассасаси ҳисобланади."},{"y": "para","x": "1.3. Арбитраж суди ўз фаолиятини қуйидагилар асосида амалга оширади:"},{"y": "para","x": "а) Ўзбекистон Республикаси Конституцияси;"},{"y": "para","x": "б) Ўзбекистон Республикасининг халқаро шартномалари;"},{"y": "para","x": "в) Ўзбекистон Республикасининг «Халқаро тижорат арбитражи тўғрисида»ги Қонуни;"},{"y": "para","x": "г) «Чет эл арбитраж қарорларини тан олиш ва ижро этиш тўғрисида»ги Нью-Йорк конвенцияси (1958 йил);"},{"y": "para","x": "д) халқаро арбитраж соҳасида умумэътироф этилган тамойиллар;"},{"y": "para","x": "е) Ўзбекистон Халқаро Арбитраж Судлари Бирлашмаси Устави;"},{"y": "para","x": "ж) мазкур Низом ва Арбитраж Регламенти."},{"y": "para","x": "1.4. Арбитраж суди ўз фаолиятини мустақиллик, холислик, тарафларнинг тенглиги, махфийлик, процессуал адолат, самарадорлик ва қонунийлик тамойиллари асосида амалга оширади."},{"y": "para","x": "1.5. Арбитраж суди давлат органларидан, маҳаллий давлат ҳокимияти органларидан, сиёсий ташкилотлардан, бошқа юридик ва жисмоний шахслардан мустақил ҳисобланади."},{"y": "para","x": "1.6. Ҳеч бир шахс Арбитраж суди, унинг Кенгаши, Раиси, арбитрлари ёки Котибиятининг процессуал фаолиятига аралашиш ҳуқуқига эга эмас."},{"y": "article","x": "2-модда. Арбитраж судининг ҳуқуқий мақоми"},{"y": "para","x": "2.1. Арбитраж суди Ўзбекистон Халқаро Арбитраж Судлари Бирлашмаси ҳузурида ташкил этилган доимий арбитраж муассасаси ҳисобланади."},{"y": "para","x": "2.2. Арбитраж суди мустақил институционал фаолият юритади ва муайян ишларни кўришда Бирлашма органларидан мустақил ҳисобланади."},{"y": "para","x": "2.3. Арбитраж суди алоҳида юридик шахс мақомига эга эмас."},{"y": "para","x": "2.4. Арбитраж судининг ташкилий, техник ва моддий таъминоти Бирлашма томонидан амалга оширилади."},{"y": "para","x": "2.5. Арбитраж судининг мустақиллигига таъсир этувчи ҳар қандай ҳаракатларга йўл қўйилмайди."},{"y": "article","x": "3-модда. Арбитраж судининг асосий мақсадлари"},{"y": "para","x": "3.1. Арбитраж судининг асосий мақсадлари қуйидагилардан иборат:"},{"y": "para","x": "а) халқаро ва маҳаллий тижорат низоларини ҳал этиш;"},{"y": "para","x": "б) инвестициявий низоларни ҳал этиш;"},{"y": "para","x": "в) иқтисодий муносабатлардан келиб чиқадиган низоларни кўриб чиқиш;"},{"y": "para","x": "г) муқобил низоларни ҳал қилиш механизмларини ривожлантириш;"},{"y": "para","x": "д) халқаро арбитраж маданиятини ривожлантириш;"},{"y": "para","x": "е) инвесторлар ҳуқуқларини самарали ҳимоя қилиш."},{"y": "para","x": "3.2. Арбитраж суди нотижорат асосда фаолият юритади."},{"y": "para","x": "3.3. Арбитраж судининг фаолияти фойда олишга қаратилмаган."},{"y": "para","x": "3.4.Арбитраж суди-юридик шахс ҳисобланмайди."},{"y": "article","x": "4-модда. Фаолиятнинг асосий тамойиллари"},{"y": "para","x": "Арбитраж суди ўз фаолиятида қуйидаги тамойилларга амал қилади:"},{"y": "para","x": "- Мустақиллик;"},{"y": "para","x": "- Холислик;"},{"y": "para","x": "- Бетарафлик;"},{"y": "para","x": "- Тарафларнинг тенглиги;"},{"y": "para","x": "- Тарафларни эшитиш ҳуқуқи;"},{"y": "para","x": "- Махфийлик;"},{"y": "para","x": "- Процессуал иқтисодийлик;"},{"y": "para","x": "- Ҳалоллик ва виждонанлик;"},{"y": "para","x": "- Халқаро арбитраж стандартларига мувофиқлик;"},{"y": "para","x": "- Ҳуқуқ устуворлиги."},{"y": "chapter","x": "II БОБ. АРБИТРАЖ СУДИНИНГ БОШҚАРУВ ТИЗИМИ"},{"y": "article","x": "5-модда. Арбитраж судининг институционал тузилиши"},{"y": "para","x": "5.1. Арбитраж суди қуйидаги органлар орқали фаолият юритади:"},{"y": "para","x": "а) Арбитраж Кенгаши (Court of Arbitration);"},{"y": "para","x": "б) Арбитраж суди Раиси;"},{"y": "para","x": "в) Раис ўринбосарлари;"},{"y": "para","x": "г) Котибият;"},{"y": "para","x": "д) Арбитрлар реестри."},{"y": "para","x": "5.2. Ушбу органлар ўз ваколатларини мустақил амалга оширадилар."},{"y": "para","x": "5.3. Муайян иш бўйича қарор қабул қилиш жараёнига бошқа органлар аралашишига йўл қўйилмайди."},{"y": "article","x": "6-модда. Арбитраж Кенгаши тузилиши"},{"y": "para","x": "6.1. Арбитраж Кенгаши Арбитраж судининг юқори институционал бошқарув органи ҳисобланади."},{"y": "para","x": "6.2. Арбитраж Кенгаши камида 5 нафар ва кўпи билан 11 нафар аъзодан иборат бўлади."},{"y": "para","x": "6.3. Кенгаш таркибига:"},{"y": "para","x": "- маҳаллий арбитраж мутахассислари;"},{"y": "para","x": "- ҳуқуқшунос олимлар;"},{"y": "para","x": "- халқаро арбитраж соҳасида тажрибага эга хорижий мутахассислар"},{"y": "para","x": "киритилиши мумкин."},{"y": "para","x": "6.4. Кенгаш таркибининг камида учдан бир қисми хорижий мутахассислардан иборат бўлиши тавсия этилади."},{"y": "para","x": "6.5. Кенгаш аъзолари Бирлашма Бошқаруви қарори билан 7 йил муддатга тасдиқланади."},{"y": "para","x": "6.6. Бир шахс қайта сайланиши мумкин."},{"y": "article","x": "7-модда. Арбитраж Кенгашининг ваколатлари"},{"y": "para","x": "Арбитраж Кенгаши:"},{"y": "para","x": "- Арбитрлар реестрини тасдиқлайди;"},{"y": "para","x": "- Арбитрлар реестрига ўзгартиш киритади;"},{"y": "para","x": "- Арбитрларнинг одоб-ахлоқ қоидаларига риоя қилинишини назорат қилади;"},{"y": "para","x": "- Арбитрни рад этиш тўғрисидаги мурожаатларни кўриб чиқади;"},{"y": "para","x": "- Арбитраж муассасасининг ривожланиш стратегиясини белгилайди;"},{"y": "para","x": "- Ички сиёсат ва стандартларни тасдиқлайди;"},{"y": "para","x": "- Йиллик ҳисоботларни кўриб чиқади;"},{"y": "para","x": "- Халқаро ҳамкорлик масалаларини мувофиқлаштиради;"},{"y": "para","x": "- Мазкур Низом ва Регламентни такомиллаштириш бўйича таклифлар ишлаб чиқади."},{"y": "article","x": "8-модда. Арбитраж суди Раисининг ваколат ва вазифалари"},{"y": "para","x": "8.1. Арбитраж суди Раиси Арбитраж Бирлашма Бошқаруви томонидан 7 йил муддатга тайинланади."},{"y": "para","x": "8.2. Раис Арбитраж судининг олий мансабдор шахси ҳисобланади."},{"y": "para","x": "8.3. Раис:"},{"y": "para","x": "- Арбитраж суди фаолиятига умумий раҳбарлик қилади;"},{"y": "para","x": "- Арбитрлар реестрини юритади;"},{"y": "para","x": "- Котибият фаолиятини мувофиқлаштиради;"},{"y": "para","x": "- халқаро алоқаларни амалга оширади;"},{"y": "para","x": "- арбитраж ишлари бўйича Низом ва Регламентда назарда тутилган ваколатларни амалга оширади;"},{"y": "para","x": "- фавқулодда арбитрни тайинлайди;"},{"y": "para","x": "- Кенгаш қарорларининг ижросини таъминлайди."},{"y": "para","x": "8.4. Раис муайян ишнинг мазмуни бўйича арбитрларга кўрсатма бериш ҳуқуқига эга эмас."},{"y": "chapter","x": "III БОБ. АРБИТРЛАР"},{"y": "article","x": "9-модда. Арбитрлар реестри"},{"y": "para","x": "9.1. Арбитраж суди раиси юқори малакали миллий ва хорижий мутахассислардан иборат Арбитрлар реестрини юритади."},{"y": "para","x": "9.2. Арбитрлар реестри тавсиявий хусусиятга эга бўлиб, тарафларнинг арбитр танлаш ҳуқуқини чекламайди."},{"y": "para","x": "9.3. Реестрга киритиладиган номзодлар:"},{"y": "para","x": "- халқаро ёки миллий ҳуқуқ соҳасида;"},{"y": "para","x": "- халқаро савдо соҳасида;"},{"y": "para","x": "- инвестиция ҳуқуқида;"},{"y": "para","x": "- молия ва банк соҳасида;"},{"y": "para","x": "- қурилиш, энергетика, транспорт ва бошқа махсус соҳаларда"},{"y": "para","x": "етарли билим ва тажрибага эга бўлиши лозим."},{"y": "para","x": "9.4. Арбитрлар реестри Арбитраж Кенгаши томонидан тасдиқланади."},{"y": "para","x": "9.5. Арбитрлар реестри ҳар йили қайта кўриб чиқилиши мумкин."},{"y": "article","x": "10-модда. Арбитрларга қўйиладиган талаблар"},{"y": "para","x": "10.1. Қуйидаги шахс арбитр бўлиши мумкин:"},{"y": "para","x": "а) тўлиқ муомала лаёқатига эга бўлган;"},{"y": "para","x": "б) юқори ахлоқий фазилатларга эга бўлган;"},{"y": "para","x": "в) олий маълумотга эга бўлган;"},{"y": "para","x": "г) иш натижасидан бевосита ёки билвосита манфаатдор бўлмаган;"},{"y": "para","x": "д) мустақил ва холис қарор қабул қилиш қобилиятига эга бўлган шахс."},{"y": "para","x": "10.2. Арбитр Ўзбекистон Республикаси фуқароси ёки хорижий давлат фуқароси бўлиши мумкин."},{"y": "para","x": "10.3. Арбитрнинг ёши чекланмайди."},{"y": "para","x": "10.4. Тарафлар низонинг хусусиятидан келиб чиқиб ҳуқуқшунос бўлмаган мутахассисларни ҳам арбитр сифатида танлаш ҳуқуқига эга."},{"y": "para","x": "10.5. Агар арбитраж ҳайъати таркибида ҳуқуқшунос бўлмаган арбитрлар мавжуд бўлса, ҳайъат раиси халқаро арбитраж соҳасида тажрибага эга бўлган ҳуқуқшунос бўлиши лозим."},{"y": "article","x": "11-модда. Арбитрнинг мустақиллиги ва холислиги"},{"y": "para","x": "11.1. Арбитр ўз вазифаларини мустақил, холис ва виждонан бажариши шарт."},{"y": "para","x": "11.2. Арбитр тарафлардан, давлат органларидан, ташкилотлардан ёки бошқа шахслардан кўрсатма қабул қилиш ҳуқуқига эга эмас."},{"y": "para","x": "11.3. Арбитр иш юритиш давомида тенглик ва адолат тамойилларига амал қилиши шарт."},{"y": "para","x": "11.4. Арбитр фақат иш материаллари ва қўлланиладиган ҳуқуқ нормалари асосида қарор қабул қилади."},{"y": "article","x": "12-модда. Манфаатлар тўқнашувини ошкор қилиш"},{"y": "para","x": "12.1. Арбитр тайинланишидан олдин мустақиллик ва холислик қасамёдини имзолайди."},{"y": "para","x": "12.2. Арбитр ўзининг мустақиллиги ёки холислигига таъсир қилиши мумкин бўлган ҳар қандай ҳолатни кечиктирмасдан тарафларга ва Котибиятга маълум қилиши шарт."},{"y": "para","x": "12.3. Қуйидагилар манфаатлар тўқнашуви сифатида баҳоланиши мумкин:"},{"y": "para","x": "- тарафлардан бири билан меҳнат муносабатлари;"},{"y": "para","x": "- молиявий манфаатдорлик;"},{"y": "para","x": "- қариндошлик муносабатлари;"},{"y": "para","x": "- доимий бизнес алоқалари;"},{"y": "para","x": "- низо предмети бўйича аввалги иштирок."},{"y": "para","x": "12.4. Ошкор қилинмаган манфаатлар тўқнашуви арбитрни рад этиш учун асос бўлиши мумкин."},{"y": "article","x": "13-модда. Арбитрни рад этиш"},{"y": "para","x": "13.1. Тараф арбитрнинг мустақиллиги ёки холислигига асосли шубҳа мавжуд бўлган тақдирда уни рад этиш ҳақида ариза бериш ҳуқуқига эга."},{"y": "para","x": "13.2. Рад этиш ҳақидаги ариза асослар маълум бўлган кундан бошлаб 15 кун ичида берилиши лозим."},{"y": "para","x": "13.3. Арбитр ўз хоҳиши билан ваколатидан воз кечиши мумкин."},{"y": "para","x": "13.4. Рад этиш тўғрисидаги масала Арбитраж Кенгаши томонидан ҳал қилинади."},{"y": "para","x": "13.5. Рад этиш қаноатлантирилган тақдирда янги арбитр мазкур Регламентда белгиланган тартибда тайинланади."},{"y": "article","x": "14-модда. Арбитрларнинг касбий этикаси"},{"y": "para","x": "14.1. Арбитрлар юқори касбий ва ахлоқий стандартларга риоя қилишлари шарт."},{"y": "para","x": "14.2. Арбитр:"},{"y": "para","x": "- махфий маълумотларни ошкор қилмаслиги;"},{"y": "para","x": "- тарафлар билан бир томонлама мулоқот қилмаслиги;"},{"y": "para","x": "- ўз ваколатларидан шахсий манфаатлар учун фойдаланмаслиги;"},{"y": "para","x": "- манфаатлар тўқнашувига йўл қўймаслиги лозим."},{"y": "para","x": "14.3. Арбитрлар Арбитраж судининг Этика кодекси талабларига риоя қилишлари шарт."},{"y": "para","x": "14.4. Этика кодекси талабларини қўпол бузган арбитр Арбитрлар реестридан чиқарилиши мумкин."},{"y": "chapter","x": "IV БОБ. АРБИТРАЖ МУҲОКАМАСИ"},{"y": "article","x": "15-модда. Арбитраж жойи"},{"y": "para","x": "15.1. Тарафлар арбитраж жойини мустақил белгилаш ҳуқуқига эга."},{"y": "para","x": "15.2. Тарафлар келишувга эришмаган тақдирда арбитраж жойи Арбитраж трибунали томонидан белгиланади."},{"y": "para","x": "15.3. Арбитраж жойини белгилашда қуйидагилар ҳисобга олинади:"},{"y": "para","x": "- тарафларнинг манфаатлари;"},{"y": "para","x": "- ишнинг хусусияти;"},{"y": "para","x": "- қулайлик;"},{"y": "para","x": "- иқтисодий самарадорлик."},{"y": "para","x": "15.4. Арбитраж жойи эшитув ўтказиладиган жой билан бир хил бўлиши шарт эмас."},{"y": "article","x": "16-модда. Арбитраж тили"},{"y": "para","x": "16.1. Тарафлар арбитраж тилини эркин белгилаш ҳуқуқига эга."},{"y": "para","x": "16.2. Келишув бўлмаган тақдирда тил Арбитраж трибунали томонидан белгиланади."},{"y": "para","x": "16.3. Арбитраж муҳокамаси:"},{"y": "para","x": "- ўзбек тилида;"},{"y": "para","x": "- рус тилида;"},{"y": "para","x": "- инглиз тилида;"},{"y": "para","x": "- тарафлар келишган бошқа тилда ўтказилиши мумкин."},{"y": "para","x": "16.4. Зарур ҳолларда таржимон жалб қилиниши мумкин."},{"y": "para","x": "16.5. Таржима харажатлари Арбитраж трибунали белгилаган тартибда тақсимланади."},{"y": "article","x": "17-модда. Электрон ва онлайн муҳокамалар"},{"y": "para","x": "17.1. Арбитраж муҳокамаси анъанавий ёки электрон шаклда ўтказилиши мумкин."},{"y": "para","x": "17.2. Ҳужжатлар электрон шаклда қабул қилиниши мумкин."},{"y": "para","x": "17.3. Эшитувлар видеоконференция орқали ташкил этилиши мумкин."},{"y": "para","x": "17.4. Электрон ҳужжатлар қоғоз шаклидаги ҳужжатлар билан тенг юридик кучга эга ҳисобланади."},{"y": "para","x": "17.5. Электрон алоқа воситаларидан фойдаланишда ахборот хавфсизлиги таъминланиши шарт."},{"y": "article","x": "18-модда. Фавқулодда арбитр"},{"y": "para","x": "18.1. Арбитраж ҳайъати шакллантирилгунга қадар тараф фавқулодда чоралар қўллаш ҳақида мурожаат қилиш ҳуқуқига эга."},{"y": "para","x": "18.2. Фавқулодда чоралар қуйидаги мақсадларда қўлланилиши мумкин:"},{"y": "para","x": "- мол-мулкни сақлаш;"},{"y": "para","x": "- далилларни сақлаб қолиш;"},{"y": "para","x": "- активларни муҳофаза қилиш;"},{"y": "para","x": "- низо предметини сақлаш."},{"y": "para","x": "18.3. Арбитраж суди Раиси мурожаат келиб тушганидан кейин 2 иш куни ичида фавқулодда арбитр тайинлайди."},{"y": "para","x": "18.4. Фавқулодда арбитр 15 кун ичида қарор қабул қилиши лозим."},{"y": "para","x": "18.5. Фавқулодда арбитр қарори арбитраж ҳайъати ташкил этилгандан кейин қайта кўриб чиқилиши мумкин."},{"y": "para","x": "18.6. Арбитраж ҳайъати фавқулодда арбитр қарорини ўзгартириш, бекор қилиш ёки кучда қолдириш ҳуқуқига эга."},{"y": "chapter","x": "V БОБ. МАХФИЙЛИК, МАЪЛУМОТЛАРНИ ҲИМОЯ ҚИЛИШ ВА ШАФФОФЛИК"},{"y": "article","x": "19-модда. Арбитраж муҳокамасининг махфийлиги"},{"y": "para","x": "19.1. Агар тарафлар бошқача келишмаган бўлсалар, арбитраж муҳокамаси махфий ҳисобланади."},{"y": "para","x": "19.2. Қуйидагилар махфий ахборот ҳисобланади:"},{"y": "para","x": "- даъво аризалари ва уларга илова қилинган ҳужжатлар;"},{"y": "para","x": "- тарафларнинг тушунтиришлари;"},{"y": "para","x": "- гувоҳлар кўрсатмалари;"},{"y": "para","x": "- эксперт хулосалари;"},{"y": "para","x": "- эшитув баённомалари;"},{"y": "para","x": "- арбитраж қарори;"},{"y": "para","x": "- муҳокама жараёнида олинган бошқа маълумотлар."},{"y": "para","x": "19.3. Арбитрлар, Котибият ходимлари, экспертлар, таржимонлар ва муҳокамада иштирок этувчи бошқа шахслар махфийликни сақлашлари шарт."},{"y": "para","x": "19.4. Махфий ахборотни ошкор қилишга фақат:"},{"y": "para","x": "а) тарафларнинг ёзма розилиги мавжуд бўлганда;"},{"y": "para","x": "б) қонунчилик талаб қилганда;"},{"y": "para","x": "в) арбитраж қарорини тан олиш ёки ижро этиш учун зарур бўлганда;"},{"y": "para","x": "г) давлат органларининг қонуний талаби асосида йўл қўйилади."},{"y": "article","x": "20-модда. Шахсий маълумотларни ҳимоя қилиш"},{"y": "para","x": "20.1. Арбитраж суди арбитраж муҳокамаси давомида олинган шахсий маълумотларни муҳофаза қилиш чораларини кўради."},{"y": "para","x": "20.2. Шахсий маълумотлар фақат арбитраж муҳокамасини амалга ошириш мақсадида қайта ишланади."},{"y": "para","x": "20.3. Шахсий маълумотлардан бошқа мақсадларда фойдаланиш тақиқланади."},{"y": "para","x": "20.4. Арбитраж суди ахборот хавфсизлиги ва киберхавфсизлик бўйича ички сиёсат қабул қилиши мумкин."},{"y": "para","x": "20.5. Электрон маълумотлар рухсатсиз киришдан ҳимоя қилиниши лозим."},{"y": "article","x": "21-модда. Арбитраж ишларининг анонимлаштирилган нашри"},{"y": "para","x": "21.1. Арбитраж амалиётини ривожлантириш мақсадида Арбитраж суди қабул қилинган қарорларнинг анонимлаштирилган шаклдаги қисқача мазмунини эълон қилиши мумкин."},{"y": "para","x": "21.2. Бундай нашрларда:"},{"y": "para","x": "- тарафларнинг номи;"},{"y": "para","x": "- тижорат сирлари;"},{"y": "para","x": "- шахсий маълумотлар;"},{"y": "para","x": "- махфий маълумотлар"},{"y": "para","x": "ошкор этилмаслиги шарт."},{"y": "para","x": "21.3. Қарорларнинг нашри тарафларнинг қонуний манфаатларига зарар етказмаслиги лозим."},{"y": "chapter","x": "VI БОБ. МОЛИЯВИЙ ФАОЛИЯТ"},{"y": "article","x": "22-модда. Арбитраж йиғимлари"},{"y": "para","x": "22.1. Арбитраж муҳокамаси арбитраж йиғимлари ва бошқа харажатлар ҳисобидан молиялаштирилади."},{"y": "para","x": "22.2. Арбитраж йиғимлари миқдори Арбитраж йиғимлари ва харажатлари тўғрисидаги Тарифлар жадвали билан белгиланади."},{"y": "para","x": "22.3. Тарифлар халқаро амалиёт ва иқтисодий асосланганлик тамойилларига мувофиқ белгиланади."},{"y": "para","x": "22.4. Тарифлар Арбитраж Кенгашининг тавсияси асосида тасдиқланади."},{"y": "article","x": "23-модда. Арбитраж харажатлари"},{"y": "para","x": "23.1. Арбитраж харажатлари таркибига қуйидагилар киради:"},{"y": "para","x": "- арбитрлар гонорари;"},{"y": "para","x": "- маъмурий йиғим;"},{"y": "para","x": "- экспертлар харажатлари;"},{"y": "para","x": "- таржимонлар хизмати;"},{"y": "para","x": "- эшитувлар билан боғлиқ харажатлар;"},{"y": "para","x": "- почта ва курьер харажатлари;"},{"y": "para","x": "- техник харажатлар."},{"y": "para","x": "23.2. Арбитраж трибунали харажатларни тарафлар ўртасида адолатли тақсимлайди."},{"y": "para","x": "23.3. Агар тарафлар келишувга эришган бўлсалар, харажатлар уларнинг келишувига мувофиқ тақсимланади."},{"y": "article","x": "24-модда. Депозитлар"},{"y": "para","x": "24.1. Арбитраж муҳокамаси харажатларини қоплаш учун тарафлардан депозит тўлаш талаб қилиниши мумкин."},{"y": "para","x": "24.2. Депозит миқдори Котибият томонидан ҳисобланади."},{"y": "para","x": "24.3. Депозит белгиланган муддатда тўланмаган тақдирда:"},{"y": "para","x": "- иш юритиш тўхтатиб турилиши;"},{"y": "para","x": "- қарши даъво кўриб чиқилмаслиги;"},{"y": "para","x": "- мурожаат қайтарилиши мумкин."},{"y": "para","x": "24.4. Ортиқча қолган маблағлар тарафларга қайтарилади."},{"y": "article","x": "25-модда. Арбитрлар гонорари"},{"y": "para","x": "25.1. Арбитрлар ўз вазифаларини бажарганликлари учун якуний қарор қабул қилганидан сўнг, Бирлашманинг ҳисоб рақамига келиб тушган арбитраж йиғимини 50% миқдорида амалдаги қонун бўйича солиқ тўловлари ушланган ҳолда ҳақ оладилар."},{"y": "para","x": "25.2. Гонорар:"},{"y": "para","x": "даъво баҳоси;"},{"y": "para","x": "-ишнинг мураккаблиги;"},{"y": "para","x": "-муҳокама давомийлиги;"},{"y": "para","x": "-сарфланган вақт инобатга олинган ҳолда белгиланади."},{"y": "para","x": "Арбитрларга гонорар қуйидаги тартибда ўтказилади"},{"y": "para","x": "-иш ҳайъатда кўрилганда, раислик этувчига -20 фоизгача;"},{"y": "para","x": "-иш бўйича ҳисоб берувчи арбитрга-10 фоизгача;"},{"y": "para","x": "-навбатдаги арбитрга-10 фоизгача;"},{"y": "para","x": "-ишда қатнашган суд мажлиси котибига-10 фоизгача."},{"y": "para","x": "Ишда котиб қатнашмаган холатда,"},{"y": "para","x": "-иш бўйича ҳисоб берувчи арбитрга-15 фоизгача;"},{"y": "para","x": "-навбатдаги арбитрга-15 фоизгача;"},{"y": "para","x": "Агар  иш битта арбитр томонидан якка тартибда кўрилган бўлса,"},{"y": "para","x": "-арбитрнинг гонорари- 40 фоизгача;"},{"y": "para","x": "-ишда қатнашган суд мажлиси котибиники-10 фоизгача."},{"y": "para","x": "Ишда котиб қатнашмаган холатда, арбитрнинг гонорари- 50 фоизгача ташкил этилади;"},{"y": "para","x": "25.3. Тарафлар ва арбитрлар қонунчиликка зид бўлмаган ҳолларда гонорарнинг бошқа ҳисоблаш усули бўйича келишишлари мумкин."},{"y": "chapter","x": "VII БОБ. АРБИТРАЖ ҚАРОРЛАРИ"},{"y": "article","x": "26-модда. Арбитраж қарорларини ҳуқуқий экспертизадан ўтказиш"},{"y": "para","x": "26.1. Арбитраж қарори имзоланишидан олдин Арбитраж судининг махсус ҳуқуқий экспертизасидан (Scrutiny) ўтказилиши мумкин."},{"y": "para","x": "26.2. Экспертизанинг мақсади:"},{"y": "para","x": "- процессуал камчиликларни бартараф этиш;"},{"y": "para","x": "- қарорнинг шаклий талабларга мувофиқлигини текшириш;"},{"y": "para","x": "- қарор ижро этилиши имкониятини ошириш."},{"y": "para","x": "26.3. Экспертиза қарор мазмунига аралашиш ҳуқуқини бермайди."},{"y": "para","x": "26.4. Арбитраж трибунали мустақил қарор қабул қилади."},{"y": "article","x": "27-модда. Арбитраж қарорининг ҳуқуқий кучи"},{"y": "para","x": "27.1. Арбитраж қарори якуний ҳисобланади."},{"y": "para","x": "27.2. Тарафлар қарорни ихтиёрий бажаришлари шарт."},{"y": "para","x": "27.3. Қарор чиқарилган кундан бошлаб кучга киради, агар қарорнинг ўзида бошқача қоида назарда тутилмаган бўлса."},{"y": "article","x": "28-модда. Арбитраж қарорларини тан олиш ва ижро этиш"},{"y": "para","x": "28.1. Арбитраж қарорлари Нью-Йорк конвенцияси ва тегишли миллий қонунчиликка мувофиқ тан олинади ва ижро этилади."},{"y": "para","x": "28.2. Қарорни ижро этиш учун мурожаат қилувчи тараф:"},{"y": "para","x": "- қарорнинг асл нусхаси;"},{"y": "para","x": "- арбитраж келишуви;"},{"y": "para","x": "- зарур ҳолларда нотариал тасдиқланган таржималарни тақдим этади."},{"y": "para","x": "28.3. Арбитраж суди қарорларининг халқаро миқёсда тан олиниши ва ижро этилишига кўмаклашади."},{"y": "chapter","x": "VIII БОБ. ШАФФОФЛИК ВА ИНСТИТУЦИОНАЛ РИВОЖЛАНИШ"},{"y": "article","x": "29-модда. Йиллик ҳисобот"},{"y": "para","x": "29.1. Арбитраж суди ҳар йили фаолият натижалари бўйича ҳисобот тайёрлаши мумкин."},{"y": "para","x": "29.2. Ҳисоботда қуйидаги маълумотлар акс эттирилиши мумкин:"},{"y": "para","x": "- ишлар сони;"},{"y": "para","x": "- давлатлар кесимида иштирокчилар;"},{"y": "para","x": "- низолар турлари;"},{"y": "para","x": "- кўриб чиқиш муддатлари;"},{"y": "para","x": "- арбитрлар статистикаси."},{"y": "para","x": "29.3. Махфий маълумотлар ҳисоботга киритилмайди."},{"y": "article","x": "30-модда. Халқаро ҳамкорлик"},{"y": "para","x": "30.1. Арбитраж суди халқаро арбитраж муассасалари билан ҳамкорлик қилиши мумкин."},{"y": "para","x": "30.2. Ҳамкорлик қуйидаги шаклларда амалга оширилади:"},{"y": "para","x": "- меморандумлар;"},{"y": "para","x": "- қўшма тадбирлар;"},{"y": "para","x": "- малака ошириш дастурлари;"},{"y": "para","x": "- илмий-тадқиқот лойиҳалари;"},{"y": "para","x": "- тажриба алмашиш."},{"y": "article","x": "31-модда. Арбитраж таълими ва малака ошириш"},{"y": "para","x": "31.1. Арбитраж суди арбитрлар ва мутахассислар учун малака ошириш дастурларини ташкил қилиши мумкин."},{"y": "para","x": "31.2. Арбитраж соҳасида илмий ва амалий тадқиқотлар қўллаб-қувватланади."},{"y": "para","x": "31.3. Ёш арбитрларни тайёрлаш дастурлари амалга оширилиши мумкин."},{"y": "chapter","x": "IX БОБ. ЯКУНЛОВЧИ ҚОИДАЛАР"},{"y": "article","x": "32-модда. Низомга ўзгартириш ва қўшимчалар киритиш"},{"y": "para","x": "32.1. Мазкур Низомга ўзгартириш ва қўшимчалар Арбитраж Кенгашининг хулосаси асосида Бирлашма Бошқаруви қарори билан киритилади."},{"y": "para","x": "32.2. Ўзгартиришлар тасдиқланган санадан бошлаб кучга киради, агар қарорда бошқача қоида назарда тутилмаган бўлса."},{"y": "article","x": "33-модда. Фаолиятни қайта ташкил этиш ёки тугатиш"},{"y": "para","x": "33.1. Арбитраж судининг фаолияти қонунчиликка мувофиқ қайта ташкил этилиши ёки тугатилиши мумкин."},{"y": "para","x": "33.2. Тугатиш тўғрисидаги қарор Бирлашма Бошқаруви томонидан қабул қилинади."},{"y": "para","x": "33.3. Тугатиш жараёни арбитраж ишларида иштирок этувчи тарафларнинг ҳуқуқларига зарар етказмаслиги лозим."},{"y": "article","x": "34-модда. Якунловчи қоида"},{"y": "para","x": "34.1. Ушбу Низом Арбитраж судининг асосий таъсис ҳужжати ҳисобланади."},{"y": "para","x": "34.2. Ушбу Низом билан тартибга солинмаган масалалар Ўзбекистон Республикасининг қонунчилиги, Арбитраж Регламенти ва халқаро арбитражнинг умумэътироф этилган тамойилларига мувофиқ ҳал этилади."},{"y": "para","x": "34.3. Низомнинг ўзбек тилидаги матни расмий матн ҳисобланади. Бошқа тиллардаги таржималар ахборот мақсадида қўлланилади."}],"reglament": [{"y": "heading","x": "ЎЗБЕКИСТОН ХАЛҚАРО АРБИТРАЖ СУДЛАРИ БИРЛАШМАСИ"},{"y": "heading","x": "ҲУЗУРИДАГИ ХАЛҚАРО  АРБИТРАЖ СУДИНИНГ"},{"y": "heading","x": "РЕГЛАМЕНТИ"},{"y": "para","x": "Тошкент-2026"},{"y": "chapter","x": "I БОБ. УМУМИЙ ҚОИДАЛАР"},{"y": "article","x": "1-модда. Қўлланиш доираси"},{"y": "para","x": "1.1. Ушбу Арбитраж Регламенти Ўзбекистон Халқаро Арбитраж Судлари Бирлашмаси ҳузуридаги Халқаро Арбитраж Суди томонидан кўриб чиқиладиган низоларга нисбатан қўлланилади."},{"y": "para","x": "1.2. Агар тарафлар ўз арбитраж келишувида мазкур Арбитраж Судига мурожаат қилишни назарда тутган бўлсалар, улар ушбу Регламентнинг амалдаги таҳририга розилик билдирган деб ҳисобланадилар."},{"y": "para","x": "1.3. Арбитраж муҳокамаси мазкур Регламент, Арбитраж Суди Низоми, қўлланиладиган ҳуқуқ ва халқаро арбитражнинг умумэътироф этилган тамойилларига мувофиқ амалга оширилади."},{"y": "para","x": "1.4. Арбитраж Суди миллий ва халқаро тижорат низолари, инвестиция низолари ҳамда тарафлар арбитраж орқали ҳал этишга келишган бошқа фуқаролик-ҳуқуқий низоларни кўриб чиқади."},{"y": "para","x": "1.5. Ушбу Регламент тарафларнинг процессуал тенглиги ва низони адолатли ҳал қилиш ҳуқуқини таъминлаш мақсадида қўлланилади."},{"y": "article","x": "2-модда. Арбитраж муҳокамасининг асосий тамойиллари"},{"y": "para","x": "2.1. Арбитраж муҳокамаси қуйидаги тамойилларга асосланади:"},{"y": "para","x": "а) қонунийлик;"},{"y": "para","x": "б) тарафлар автономияси;"},{"y": "para","x": "в) арбитрларнинг мустақиллиги ва холислиги;"},{"y": "para","x": "г) тарафларнинг тенглиги;"},{"y": "para","x": "д) тортишувчилик;"},{"y": "para","x": "е) процессуал иқтисодкорлик;"},{"y": "para","x": "ж) махфийлик;"},{"y": "para","x": "з) ҳалоллик ва виждонлилик."},{"y": "para","x": "2.2. Трибунал ҳар бир тарафга ўз позициясини тақдим этиш учун тенг ва оқилона имконият яратиши шарт."},{"y": "para","x": "2.3. Ҳеч бир тарафга асоссиз афзаллик берилмаслиги лозим."},{"y": "article","x": "3-модда. Атамалар"},{"y": "para","x": "Ушбу Регламентда қуйидаги атамалар қўлланилади:"},{"y": "para","x": "Арбитраж Суди — Ўзбекистон Халқаро Арбитраж Судлари Бирлашмаси ҳузуридаги Халқаро Арбитраж Суди."},{"y": "para","x": "Арбитраж Кенгаши — Арбитраж Судининг доимий бошқарув органи."},{"y": "para","x": "Котибият — Арбитраж Судининг маъмурий аппарати."},{"y": "para","x": "Трибунал — муайян ишни кўриб чиқиш учун тайинланган бир ёки бир нечта арбитрлар таркиби."},{"y": "para","x": "Даъвогар — арбитраж муҳокамасини бошлаган тараф."},{"y": "para","x": "Жавобгар — нисбатан талаб қўйилган тараф."},{"y": "para","x": "Арбитраж келишуви — тарафларнинг низони арбитражда ҳал қилиш ҳақидаги келишуви."},{"y": "para","x": "Арбитраж жойи — арбитражнинг юридик ўтказилиш жойи."},{"y": "para","x": "Электрон хабарнома — электрон почта, электрон платформа ёки бошқа рақамли алоқа воситалари орқали юборилган хабар."},{"y": "article","x": "4-модда. Хабарномалар ва алоқа воситалари"},{"y": "para","x": "4.1. Барча процессуал ҳужжатлар ва хабарномалар ёзма шаклда тақдим этилади."},{"y": "para","x": "4.2. Ҳужжатлар қуйидаги усуллар орқали юборилиши мумкин:"},{"y": "para","x": "- электрон почта;"},{"y": "para","x": "- махсус электрон платформа;"},{"y": "para","x": "- курьер хизмати;"},{"y": "para","x": "- почта хизмати;"},{"y": "para","x": "- тарафлар келишган бошқа усуллар."},{"y": "para","x": "4.3. Электрон шаклда юборилган хабарнома юборилган санада етказилган деб ҳисобланади, агар бошқача исботланмаган бўлса."},{"y": "para","x": "4.4. Тараф ўз манзили ёки электрон почтасини ўзгартирган тақдирда бу ҳақда Котибият ва бошқа тарафни дарҳол хабардор қилиши шарт."},{"y": "article","x": "5-модда. Муддатларни ҳисоблаш"},{"y": "para","x": "5.1. Регламентда белгиланган муддатлар календарь кунларда ҳисобланади."},{"y": "para","x": "5.2. Муддат ҳисоблаш хабарнома олинган кундан кейинги кундан бошланади."},{"y": "para","x": "5.3. Агар муддатнинг охирги куни дам олиш ёки байрам кунига тўғри келса, муддат кейинги иш кунида тугайди."},{"y": "para","x": "5.4. Трибунал асосли сабаблар мавжуд бўлган тақдирда процессуал муддатларни узайтириши мумкин."},{"y": "chapter","x": "II БОБ. АРБИТРАЖ ИШИНИ БОШЛАШ"},{"y": "article","x": "6-модда. Даъво аризаси"},{"y": "para","x": "6.1. Арбитраж муҳокамаси Даъвогарнинг даъво аризаси тақдим этиши билан бошланади."},{"y": "para","x": "6.2. Даъво аризасида қуйидагилар кўрсатилиши лозим:"},{"y": "para","x": "а) тарафларнинг тўлиқ номи ва реквизитлари;"},{"y": "para","x": "б) арбитраж келишувининг нусхаси;"},{"y": "para","x": "в) низонинг қисқача тавсифи;"},{"y": "para","x": "г) талаблар мазмуни;"},{"y": "para","x": "д) талаблар асослантирилаётган ҳолатлар;"},{"y": "para","x": "е) даъво баҳоси;"},{"y": "para","x": "ж) арбитр тайинлаш бўйича таклифлар;"},{"y": "para","x": "з) илова қилинаётган ҳужжатлар рўйхати."},{"y": "para","x": "6.3. Даъво аризасига талабларни тасдиқловчи ҳужжатлар илова қилинади."},{"y": "chapter","x": "II БОБ. АРБИТРАЖ ИШИНИ БОШЛАШ"},{"y": "article","x": "7-модда. Даъво аризасини қабул қилиш"},{"y": "para","x": "7.1. Котибият даъво аризаси ва унга илова қилинган ҳужжатларни дастлабки тарзда текширади."},{"y": "para","x": "7.2. Агар даъво аризаси мазкур Регламент талабларига жавоб бермаса, Котибият Даъвогарга камчиликларни бартараф этиш учун муддат беради."},{"y": "para","x": "7.3. Белгиланган муддат ичида камчиликлар бартараф этилмаган тақдирда, даъво аризаси қайтарилиши мумкин."},{"y": "para","x": "7.4. Даъво аризасини қайтариш Даъвогарни камчиликлар бартараф этилгандан кейин қайта мурожаат қилиш ҳуқуқидан маҳрум қилмайди."},{"y": "article","x": "8-модда. Арбитраж ишининг бошланган санаси"},{"y": "para","x": "8.1. Арбитраж иши Котибият томонидан даъво аризаси қабул қилинган ва белгиланган йиғим тўланган санада бошланган деб ҳисобланади."},{"y": "para","x": "8.2. Котибият ишни рўйхатга олгандан кейин иш рақамини беради."},{"y": "para","x": "8.3. Даъво аризасининг нусхаси ва илова қилинган ҳужжатлар Жавобгарга юборилади."},{"y": "article","x": "9-модда. Жавоб аризаси"},{"y": "para","x": "9.1. Жавобгар даъво аризасини олган кундан бошлаб 30 кун ичида жавоб аризасини тақдим этади."},{"y": "para","x": "9.2. Жавоб аризасида қуйидагилар кўрсатилиши лозим:"},{"y": "para","x": "а) Жавобгарнинг номи ва реквизитлари;"},{"y": "para","x": "б) талабларга муносабати;"},{"y": "para","x": "в) эътирозларнинг ҳуқуқий ва фактик асослари;"},{"y": "para","x": "г) арбитр тайинлаш бўйича таклифлар;"},{"y": "para","x": "д) тақдим этилаётган далиллар рўйхати."},{"y": "para","x": "9.3. Асосли сабаблар мавжуд бўлган тақдирда Трибунал ёки Котибият жавоб тақдим этиш муддатини узайтириши мумкин."},{"y": "para","x": "9.4. Жавоб аризасининг тақдим этилмаганлиги ишни кўришга тўсқинлик қилмайди."},{"y": "article","x": "10-модда. Қарши даъво"},{"y": "para","x": "10.1. Жавобгар қарши даъво киритиш ҳуқуқига эга."},{"y": "para","x": "10.2. Қарши даъво мазкур Регламентда даъво аризаси учун белгиланган талабларга мувофиқ бўлиши лозим."},{"y": "para","x": "10.3. Қарши даъво учун тегишли арбитраж йиғими тўланади."},{"y": "para","x": "10.4. Трибунал қарши даъвони асосий иш билан биргаликда ёки алоҳида кўриб чиқиш тўғрисида қарор қабул қилиши мумкин."},{"y": "article","x": "11-модда. Қўшимча талаблар"},{"y": "para","x": "11.1. Тарафлар муҳокама давомида ўз талаблари ёки эътирозларини ўзгартириш ёки тўлдириш ҳуқуқига эга."},{"y": "para","x": "11.2. Трибунал бундай ўзгартишлар:"},{"y": "para","x": "- ишни кечиктирмаслиги;"},{"y": "para","x": "- бошқа тараф ҳуқуқларига зарар етказмаслиги;"},{"y": "para","x": "- адолат тамойилига зид бўлмаслиги"},{"y": "para","x": "шартлари билан қабул қилиниши мумкин."},{"y": "para","x": "11.3. Трибунал янги талабларни қабул қилиш ёки рад этиш ҳақида асослантирилган қарор қабул қилади."},{"y": "chapter","x": "III БОБ. АРБИТРАЖ ТРИБУНАЛИ"},{"y": "article","x": "12-модда. Арбитрлар сони"},{"y": "para","x": "12.1. Низо бир нафар ёки уч нафар арбитрдан иборат Трибунал томонидан кўриб чиқилади."},{"y": "para","x": "12.2. Тарафлар арбитрлар сонини мустақил белгилаш ҳуқуқига эга."},{"y": "para","x": "12.3. Агар тарафлар келишувга эришмаган бўлса:"},{"y": "para","x": "а) одатда иш бир нафар арбитр томонидан;"},{"y": "para","x": "б) ишнинг мураккаблиги, қиймати ёки аҳамиятидан келиб чиқиб уч нафар арбитр томонидан"},{"y": "para","x": "кўриб чиқилиши мумкин."},{"y": "para","x": "12.4. Арбитрлар сони ҳақидаги қарорни Арбитраж Кенгаши қабул қилиши мумкин."},{"y": "article","x": "13-модда. Арбитрларни тайинлаш"},{"y": "para","x": "13.1. Якка арбитр тарафларнинг келишувига кўра тайинланади."},{"y": "para","x": "13.2. Агар тарафлар 30 кун ичида келишувга эришмасалар, якка арбитр Арбитраж Кенгаши ёки Арбитраж Суди Раиси томонидан тайинланади."},{"y": "para","x": "13.3. Уч нафар арбитр иштирок этадиган ишда:"},{"y": "para","x": "- Даъвогар бир арбитр тайинлайди;"},{"y": "para","x": "- Жавобгар бир арбитр тайинлайди."},{"y": "para","x": "13.4. Тайинланган икки арбитр Трибунал раиси бўладиган учинчи арбитрни танлайди."},{"y": "para","x": "13.5. Агар арбитрлар белгиланган муддатда келишувга эришмасалар, Трибунал раиси Арбитраж Кенгаши томонидан тайинланади."},{"y": "article","x": "14-модда. Арбитрнинг мустақиллиги ва холислиги"},{"y": "para","x": "14.1. Ҳар бир арбитр мустақил ва холис бўлиши шарт."},{"y": "para","x": "14.2. Арбитр тайинланишидан олдин мустақиллик ва холислик декларациясини тақдим этади."},{"y": "para","x": "14.3. Арбитр тарафлардан бири билан муносабатлари унинг холислигига шубҳа туғдириши мумкин бўлган ҳар қандай ҳолатни ошкор қилиши шарт."},{"y": "para","x": "14.4. Ошкор қилиш мажбурияти муҳокама тугагунига қадар сақланади."},{"y": "article","x": "15-модда. Манфаатлар тўқнашуви"},{"y": "para","x": "15.1. Қуйидаги ҳолатлар манфаатлар тўқнашуви сифатида баҳоланиши мумкин:"},{"y": "para","x": "- молиявий манфаатдорлик;"},{"y": "para","x": "- меҳнат муносабатлари;"},{"y": "para","x": "- доимий хизмат кўрсатиш муносабатлари;"},{"y": "para","x": "- қариндошлик алоқалари;"},{"y": "para","x": "- иш натижасидан манфаатдорлик."},{"y": "para","x": "15.2. Манфаатлар тўқнашуви ҳақидаги маълумот дарҳол Котибият ва тарафларга маълум қилиниши лозим."},{"y": "para","x": "15.3. Трибунал мустақиллигига таъсир қилувчи ҳолатлар юзага келганда Арбитраж Кенгаши тегишли қарор қабул қилади."},{"y": "article","x": "16-модда. Арбитрни рад этиш"},{"y": "para","x": "16.1. Тараф арбитрнинг мустақиллиги ёки холислигига асосли шубҳа мавжуд бўлган тақдирда уни рад этиш ҳақида ариза бериш ҳуқуқига эга."},{"y": "para","x": "16.2. Рад этиш ҳақидаги ариза тегишли ҳолат маълум бўлган кундан бошлаб 15 кун ичида берилиши лозим."},{"y": "para","x": "16.3. Ариза ёзма шаклда асослантирилган бўлиши шарт."},{"y": "para","x": "16.4. Рад этиш тўғрисидаги масала Арбитраж Кенгаши томонидан ҳал қилинади."},{"y": "article","x": "17-модда. Арбитр ваколатининг тугатилиши"},{"y": "para","x": "17.1. Қуйидаги ҳолларда арбитрнинг ваколати тугатилади:"},{"y": "para","x": "- ўз хоҳишига кўра истеъфо берганда;"},{"y": "para","x": "- рад этиш қаноатлантирилганда;"},{"y": "para","x": "- вазифаларини бажариш имкони бўлмаганда;"},{"y": "para","x": "- вафот этганда."},{"y": "para","x": "17.2. Ваколат тугатилган тақдирда янги арбитр мазкур Регламентга мувофиқ тайинланади."},{"y": "article","x": "18-модда. Янги арбитр тайинлаш"},{"y": "para","x": "18.1. Янги арбитр аввалги арбитр тайинланган тартибда тайинланади."},{"y": "para","x": "18.2. Трибунал ишнинг ҳолатларидан келиб чиқиб процессуал ҳаракатларни қайта амалга ошириш ёки амалга оширмаслик тўғрисида қарор қабул қилади."},{"y": "chapter","x": "IV БОБ. ЮРИСДИКЦИЯ"},{"y": "article","x": "19-модда. Арбитраж келишувининг мустақиллиги"},{"y": "para","x": "19.1. Арбитраж келишуви асосий шартномадан мустақил ҳисобланади."},{"y": "para","x": "19.2. Асосий шартноманинг ҳақиқий эмас деб топилиши, бекор қилиниши ёки тугатилиши арбитраж келишувининг автоматик равишда ҳақиқий эмас деб топилишига олиб келмайди."},{"y": "para","x": "19.3. Арбитраж келишувининг ҳақиқийлиги алоҳида баҳоланади."},{"y": "para","x": "19.4. Тарафлар арбитраж келишувини ёзма шаклда тузишлари лозим."},{"y": "article","x": "20-модда. Трибуналнинг ўз юрисдикцияси бўйича қарор қабул қилиш ҳуқуқи"},{"y": "para","x": "20.1. Арбитраж трибунали ўз юрисдикцияси масаласини мустақил ҳал қилиш ҳуқуқига эга."},{"y": "para","x": "20.2. Трибунал қуйидаги масалаларни кўриб чиқиши мумкин:"},{"y": "para","x": "а) арбитраж келишувининг мавжудлиги;"},{"y": "para","x": "б) арбитраж келишувининг ҳақиқийлиги;"},{"y": "para","x": "в) арбитраж келишувининг амал қилиш доираси;"},{"y": "para","x": "г) низонинг арбитражда кўриб чиқилиши мумкинлиги."},{"y": "para","x": "20.3. Юрисдикция бўйича қарор:"},{"y": "para","x": "- алоҳида қарор билан;"},{"y": "para","x": "- ёки якуний қарор таркибида"},{"y": "para","x": "қабул қилиниши мумкин."},{"y": "article","x": "21-модда. Юрисдикцияга оид эътирозлар"},{"y": "para","x": "21.1. Юрисдикцияга оид эътирозлар мумкин қадар эрта босқичда билдирилиши лозим."},{"y": "para","x": "21.2. Арбитр тайинлашда иштирок этиш юрисдикцияга эътироз билдириш ҳуқуқидан маҳрум қилмайди."},{"y": "para","x": "21.3. Трибунал кечикиб берилган эътирозни асосли сабаблар мавжуд бўлган тақдирда қабул қилиши мумкин."},{"y": "chapter","x": "V БОБ. АРБИТРАЖ МУҲОКАМАСИ"},{"y": "article","x": "22-модда. Процессуал жадвал"},{"y": "para","x": "22.1. Трибунал тузилганидан кейин мумкин қадар тез муддатда процессуал жадвал тасдиқланади."},{"y": "para","x": "22.2. Процессуал жадвалда қуйидагилар белгиланади:"},{"y": "para","x": "- ёзма баёнотлар тақдим этиш муддатлари;"},{"y": "para","x": "- далиллар тақдим этиш муддатлари;"},{"y": "para","x": "- эшитув санаси;"},{"y": "para","x": "- бошқа процессуал ҳаракатлар."},{"y": "para","x": "22.3. Трибунал заруратга кўра жадвалга ўзгартиш киритиши мумкин."},{"y": "article","x": "23-модда. Арбитраж тили"},{"y": "para","x": "23.1. Арбитраж муҳокамаси тарафлар келишган тилда олиб борилади."},{"y": "para","x": "23.2. Келишув мавжуд бўлмаган тақдирда тил Трибунал томонидан белгиланади."},{"y": "para","x": "23.3. Трибунал қуйидагиларни ҳисобга олади:"},{"y": "para","x": "- шартнома тили;"},{"y": "para","x": "- тарафларнинг тили;"},{"y": "para","x": "- далиллар тили;"},{"y": "para","x": "- ишнинг хусусияти."},{"y": "para","x": "23.4. Зарур ҳолларда таржимон жалб қилиниши мумкин."},{"y": "article","x": "24-модда. Арбитраж жойи"},{"y": "para","x": "24.1. Арбитраж жойи тарафлар келишувига кўра белгиланади."},{"y": "para","x": "24.2. Келишув бўлмаган тақдирда арбитраж жойи Трибунал томонидан белгиланади."},{"y": "para","x": "24.3. Арбитраж жойини белгилашда қуйидагилар ҳисобга олинади:"},{"y": "para","x": "- тарафлар учун қулайлик;"},{"y": "para","x": "- низонинг хусусияти;"},{"y": "para","x": "- қўлланиладиган ҳуқуқ;"},{"y": "para","x": "- процессуал самарадорлик."},{"y": "para","x": "24.4. Эшитувлар арбитраж жойидан бошқа ерда ҳам ўтказилиши мумкин."},{"y": "article","x": "25-модда. Процессуал буйруқлар"},{"y": "para","x": "25.1. Трибунал муҳокамани самарали ташкил қилиш мақсадида процессуал буйруқлар чиқариши мумкин."},{"y": "para","x": "25.2. Процессуал буйруқлар қуйидаги масалаларга оид бўлиши мумкин:"},{"y": "para","x": "- далиллар;"},{"y": "para","x": "- эшитувлар;"},{"y": "para","x": "- экспертизалар;"},{"y": "para","x": "- махфийлик;"},{"y": "para","x": "- муддатлар."},{"y": "para","x": "25.3. Тарафлар процессуал буйруқларга риоя қилишлари шарт."},{"y": "article","x": "26-модда. Далиллар"},{"y": "para","x": "26.1. Ҳар бир тараф ўз талаблари ва эътирозларини исботлаши шарт."},{"y": "para","x": "26.2. Далиллар қуйидаги шаклларда тақдим қилиниши мумкин:"},{"y": "para","x": "- ҳужжатлар;"},{"y": "para","x": "- электрон маълумотлар;"},{"y": "para","x": "- гувоҳ кўрсатмалари;"},{"y": "para","x": "- эксперт хулосалари;"},{"y": "para","x": "- ашёвий далиллар;"},{"y": "para","x": "- бошқа мақбул далиллар."},{"y": "para","x": "26.3. Трибунал далилларнинг мақбуллиги, ишончлилиги ва аҳамиятини баҳолайди."},{"y": "article","x": "27-модда. Ҳужжатларни тақдим этиш"},{"y": "para","x": "27.1. Тараф Трибуналга муайян ҳужжатларни тақдим этиш ҳақида илтимоснома киритиш ҳуқуқига эга."},{"y": "para","x": "27.2. Илтимосномада қуйидагилар кўрсатилиши лозим:"},{"y": "para","x": "а) талаб қилинаётган ҳужжат;"},{"y": "para","x": "б) унинг эҳтимолий мавжудлиги;"},{"y": "para","x": "в) иш учун аҳамияти;"},{"y": "para","x": "г) нега мазкур ҳужжат бошқа тараф ихтиёрида эканлиги."},{"y": "para","x": "27.3. Трибунал илтимосномани қаноатлантириши ёки рад этиши мумкин."},{"y": "para","x": "27.4. Асоссиз равишда ҳужжат тақдим этилмаганлиги далилларни баҳолашда ҳисобга олиниши мумкин."},{"y": "article","x": "28-модда. Гувоҳлар"},{"y": "para","x": "28.1. Ҳар бир тараф гувоҳларни тақдим қилиш ҳуқуқига эга."},{"y": "para","x": "28.2. Гувоҳ тараф ходими, раҳбари ёки бошқа манфаатдор шахс бўлиши мумкин."},{"y": "para","x": "28.3. Трибунал гувоҳнинг иштирокини таъминлаш чораларини белгилайди."},{"y": "para","x": "28.4. Гувоҳ кўрсатмаси ёзма ёки оғзаки шаклда берилиши мумкин."},{"y": "article","x": "29-модда. Гувоҳларнинг ёзма кўрсатмалари"},{"y": "para","x": "29.1. Гувоҳ кўрсатмалари ёзма шаклда тақдим қилиниши мумкин."},{"y": "para","x": "29.2. Кўрсатмада қуйидагилар бўлиши лозим:"},{"y": "para","x": "- Ф.И.Ш.;"},{"y": "para","x": "- лавозими;"},{"y": "para","x": "- тарафлар билан алоқаси;"},{"y": "para","x": "- ишга оид маълумотлар;"},{"y": "para","x": "- имзо ва сана."},{"y": "para","x": "29.3. Трибунал гувоҳни эшитувда иштирок этишга чақириши мумкин."},{"y": "article","x": "30-модда. Экспертлар"},{"y": "para","x": "30.1. Тарафлар мустақил экспертларни жалб қилиш ҳуқуқига эга."},{"y": "para","x": "30.2. Трибунал ҳам мустақил эксперт тайинлаши мумкин."},{"y": "para","x": "30.3. Эксперт ўз вазифаларини холис ва мустақил бажариши шарт."},{"y": "para","x": "30.4. Эксперт манфаатлар тўқнашуви ҳақида маълум қилиши лозим."},{"y": "article","x": "31-модда. Эксперт хулосалари"},{"y": "para","x": "31.1. Эксперт хулосаси ёзма шаклда тақдим қилинади."},{"y": "para","x": "31.2. Хулосада:"},{"y": "para","x": "- тадқиқот предмети;"},{"y": "para","x": "- қўлланган усуллар;"},{"y": "para","x": "- таҳлил;"},{"y": "para","x": "- хулоса"},{"y": "para","x": "кўрсатилиши лозим."},{"y": "para","x": "31.3. Трибунал экспертдан қўшимча тушунтиришлар талаб қилиши мумкин."},{"y": "article","x": "32-модда. Кросс-сўроқ"},{"y": "para","x": "32.1. Ҳар бир тараф гувоҳлар ва экспертларга савол бериш ҳуқуқига эга."},{"y": "para","x": "32.2. Саволлар ишга алоқадор бўлиши лозим."},{"y": "para","x": "32.3. Трибунал номувофиқ ёки такрорий саволларни чеклаши мумкин."},{"y": "article","x": "33-модда. Экспериментал далиллар"},{"y": "para","x": "33.1. Трибунал зарур ҳолларда текширув, синов ёки эксперимент натижаларини далил сифатида қабул қилиши мумкин."},{"y": "para","x": "33.2. Эксперимент:"},{"y": "para","x": "- холис;"},{"y": "para","x": "- текшириладиган;"},{"y": "para","x": "- ишончли"},{"y": "para","x": "усулларда ўтказилиши лозим."},{"y": "para","x": "33.3. Тарафларга экспериментда иштирок этиш имконияти берилиши мумкин."},{"y": "article","x": "34-модда. Техник йиғилишлар ва эксперт конференциялари"},{"y": "para","x": "34.1. Трибунал экспертлар иштирокида техник йиғилишлар ўтказиши мумкин."},{"y": "para","x": "34.2. Трибунал экспертлардан умумий ва баҳсли масалалар бўйича қўшма ҳисобот тайёрлашни талаб қилиши мумкин."},{"y": "para","x": "34.3. Бундай йиғилишлар муҳокамани самарали ташкил қилиш мақсадида ўтказилади."},{"y": "article","x": "35-модда. Онлайн ва гибрид эшитувлар"},{"y": "para","x": "35.1. Эшитувлар:"},{"y": "para","x": "- жисмоний иштирокда;"},{"y": "para","x": "- видеоконференция орқали;"},{"y": "para","x": "- гибрид шаклда"},{"y": "para","x": "ўтказилиши мумкин."},{"y": "para","x": "35.2. Онлайн эшитув иштирокчиларнинг тенг ҳуқуқли иштирокини таъминлаши лозим."},{"y": "para","x": "35.3. Трибунал электрон далиллар ва ахборот хавфсизлигини таъминлаш бўйича кўрсатмалар бериши мумкин."},{"y": "chapter","x": "VI БОБ. ҚЎШИМЧА ТАРАФЛАР ВА ИШЛАРНИ БИРЛАШТИРИШ"},{"y": "article","x": "36-модда. Қўшимча тарафни жалб қилиш"},{"y": "para","x": "36.1. Арбитраж муҳокамасида иштирок этмаётган шахс қўшимча тараф сифатида жалб қилиниши мумкин."},{"y": "para","x": "36.2. Қўшимча тарафни жалб қилиш тўғрисидаги илтимоснома тарафлардан бири ёки қўшимча тарафнинг ўзи томонидан берилиши мумкин."},{"y": "para","x": "36.3. Қўшимча тараф қуйидаги ҳолларда жалб қилиниши мумкин:"},{"y": "para","x": "а) арбитраж келишувининг иштирокчиси бўлса;"},{"y": "para","x": "б) низо натижасидан ҳуқуқий манфаатдор бўлса;"},{"y": "para","x": "в) низони тўлиқ ва самарали ҳал қилиш учун унинг иштироки зарур бўлса."},{"y": "para","x": "36.4. Трибунал ёки Арбитраж Кенгаши қўшимча тарафни жалб қилиш ҳақида қарор қабул қилишда барча иштирокчиларнинг ҳуқуқ ва манфаатларини ҳисобга олади."},{"y": "para","x": "36.5. Қўшимча тараф жалб қилинганидан кейин унга иш материаллари тақдим этилади ва ўз позициясини билдириш учун етарли имконият берилади."},{"y": "article","x": "37-модда. Арбитраж ишларини бирлаштириш"},{"y": "para","x": "37.1. Арбитраж Кенгаши икки ёки ундан ортиқ арбитраж ишларини битта иш юритувига бирлаштириши мумкин."},{"y": "para","x": "37.2. Қуйидаги ҳолларда ишлар бирлаштирилиши мумкин:"},{"y": "para","x": "а) барча тарафлар розилик билдирганда;"},{"y": "para","x": "б) ишлар бир хил арбитраж келишувига асосланган бўлса;"},{"y": "para","x": "в) ишлар ўзаро боғлиқ шартномалардан келиб чиққан бўлса;"},{"y": "para","x": "г) ишлар бўйича ҳуқуқий ва фактик масалалар ўзаро боғлиқ бўлса."},{"y": "para","x": "37.3. Бирлаштириш ҳақида қарор қабул қилишда қуйидагилар ҳисобга олинади:"},{"y": "para","x": "- процессуал самарадорлик;"},{"y": "para","x": "- харажатларни тежаш;"},{"y": "para","x": "- қарорларнинг ўзаро зид бўлиб қолиш эҳтимоли."},{"y": "para","x": "37.4. Бирлаштирилган ишлар бўйича арбитраж ҳайъати Арбитраж Кенгаши томонидан белгиланади."},{"y": "chapter","x": "VII БОБ. ВАҚТИНЧАЛИК ВА ТАЪМИНЛОВ ЧОРАЛАРИ"},{"y": "article","x": "38-модда. Вақтинчалик чоралар"},{"y": "para","x": "38.1. Трибунал тарафнинг аризасига кўра вақтинчалик ёки таъминлов чораларини қўллаши мумкин."},{"y": "para","x": "38.2. Бундай чоралар қуйидагиларга қаратилган бўлиши мумкин:"},{"y": "para","x": "а) низо предметини сақлаш;"},{"y": "para","x": "б) мол-мулкни муҳофаза қилиш;"},{"y": "para","x": "в) активларни сақлаб қолиш;"},{"y": "para","x": "г) далилларни сақлаш;"},{"y": "para","x": "д) зарар етказилишининг олдини олиш."},{"y": "para","x": "38.3. Вақтинчалик чоралар ҳақидаги ариза асослантирилган бўлиши лозим."},{"y": "para","x": "38.4. Трибунал тарафлардан қўшимча далиллар талаб қилиши мумкин."},{"y": "article","x": "39-модда. Қарши таъминот"},{"y": "para","x": "39.1. Трибунал тарафнинг илтимосига кўра харажатларни қоплаш учун қарши таъминот тақдим этишни талаб қилиши мумкин."},{"y": "para","x": "39.2. Қарши таъминотни белгилашда қуйидагилар ҳисобга олинади:"},{"y": "para","x": "- даъвонинг хусусияти;"},{"y": "para","x": "- молиявий хавфлар;"},{"y": "para","x": "- ишнинг ҳолатлари."},{"y": "para","x": "39.3. Қарши таъминот пул маблағи, банк кафолати ёки бошқа муносиб шаклда тақдим қилиниши мумкин."},{"y": "article","x": "40-модда. Фавқулодда арбитр"},{"y": "para","x": "40.1. Арбитраж ҳайъати шакллантирилгунга қадар тараф фавқулодда чораларни қўллаш ҳақида мурожаат қилиши мумкин."},{"y": "para","x": "40.2. Мурожаат арбитраж иши бошланганидан кейин ёки даъво билан бир вақтда берилиши мумкин."},{"y": "para","x": "40.3. Арбитраж Суди Раиси мурожаат келиб тушганидан кейин икки иш куни ичида фавқулодда арбитрни тайинлайди."},{"y": "para","x": "40.4. Фавқулодда арбитр мустақиллик ва холислик декларациясини тақдим этади."},{"y": "para","x": "40.5. Фавқулодда арбитр иш материалларини олган кундан бошлаб ўн беш кун ичида қарор қабул қилиши лозим."},{"y": "para","x": "40.6. Фавқулодда арбитр қарори вақтинчалик хусусиятга эга."},{"y": "para","x": "40.7. Арбитраж ҳайъати ташкил этилгандан кейин мазкур қарорни:"},{"y": "para","x": "- ўз кучида қолдириши;"},{"y": "para","x": "- ўзгартириши;"},{"y": "para","x": "- бекор қилиши мумкин."},{"y": "chapter","x": "VIII БОБ. ТЕЗЛАШТИРИЛГАН АРБИТРАЖ"},{"y": "article","x": "41-модда. Тезлаштирилган тартибни қўллаш"},{"y": "para","x": "41.1. Қуйидаги ҳолларда тезлаштирилган арбитраж тартиби қўлланилиши мумкин:"},{"y": "para","x": "а) тарафлар бу ҳақда келишган бўлса;"},{"y": "para","x": "б) даъво баҳоси 500 000 АҚШ долларидан ошмаса;"},{"y": "para","x": "в) иш алоҳида шошилинч хусусиятга эга бўлса."},{"y": "para","x": "41.2. Арбитраж Кенгаши тезлаштирилган тартибни қўллаш тўғрисида қарор қабул қилади."},{"y": "article","x": "42-модда. Тезлаштирилган арбитражнинг хусусиятлари"},{"y": "para","x": "42.1. Иш одатда якка арбитр томонидан кўриб чиқилади."},{"y": "para","x": "42.2. Ёзма баёнотлар сони чекланиши мумкин."},{"y": "para","x": "42.3. Трибунал эшитув ўтказмасдан ишни ҳужжатлар асосида ҳал қилиш ҳуқуқига эга."},{"y": "para","x": "42.4. Процессуал муддатлар қисқартирилиши мумкин."},{"y": "article","x": "43-модда. Тезлаштирилган қарор чиқариш муддати"},{"y": "para","x": "43.1. Арбитраж қарори, қоида тариқасида, иш бўйича сўнгги материаллар тақдим этилган кундан бошлаб олти ой ичида қабул қилиниши лозим."},{"y": "para","x": "43.2. Зарур ҳолларда Арбитраж Кенгаши ушбу муддатни узайтириши мумкин."},{"y": "chapter","x": "IX БОБ. МЕДИАЦИЯ ВА ЯРАШУВ"},{"y": "article","x": "44-модда. Медиациядан фойдаланиш ҳуқуқи"},{"y": "para","x": "44.1. Тарафлар низони медиация орқали ҳал қилишга уриниб кўриш ҳуқуқига эга."},{"y": "para","x": "44.2. Арбитраж муҳокамаси давомида ҳам медиация ўтказилиши мумкин."},{"y": "para","x": "44.3. Медиация ўтказилиши арбитраж муҳокамасини вақтинча тўхтатиш учун асос бўлиши мумкин."},{"y": "article","x": "45-модда. Ярашув битими"},{"y": "para","x": "45.1. Тарафлар ярашувга эришган тақдирда бу ҳақда ёзма битим тузадилар."},{"y": "para","x": "45.2. Тарафларнинг илтимосига кўра Трибунал ярашув битимини келишилган шартлар асосида арбитраж қарори шаклида расмийлаштириши мумкин."},{"y": "para","x": "45.3. Бундай қарор бошқа арбитраж қарорлари билан бир хил ҳуқуқий кучга эга бўлади."},{"y": "chapter","x": "X БОБ. ҚЎЛЛАНИЛАДИГАН ҲУҚУҚ"},{"y": "article","x": "46-модда. Низога қўлланиладиган моддий ҳуқуқ"},{"y": "para","x": "46.1. Арбитраж трибунали низони тарафлар томонидан танланган ҳуқуқ нормалари асосида ҳал қилади."},{"y": "para","x": "46.2. Тарафларнинг ҳуқуқ танлаши муайян давлат ҳуқуқига ёки ҳуқуқ нормалари тизимига нисбатан амал қилиши мумкин."},{"y": "para","x": "46.3. Агар тарафлар қўлланиладиган ҳуқуқни танламаган бўлсалар, Трибунал низо билан энг яқин боғлиқ бўлган ҳуқуқни қўллайди."},{"y": "para","x": "46.4. Трибунал шартнома шартларини ва тегишли савдо одатларини ҳисобга олади."},{"y": "article","x": "47-модда. Халқаро савдо одатлари ва савдо ҳуқуқи"},{"y": "para","x": "47.1. Трибунал тарафларнинг келишуви ёки иш ҳолатларидан келиб чиқиб халқаро савдо одатлари ва умумэътироф этилган тижорат амалиётини ҳисобга олиши мумкин."},{"y": "para","x": "47.2. Трибунал қуйидагилардан фойдаланиши мумкин:"},{"y": "para","x": "- халқаро савдо одатлари;"},{"y": "para","x": "- UNIDROIT принциплари;"},{"y": "para","x": "- Савдо ҳуқуқи тамойиллари;"},{"y": "para","x": "- соҳавий тижорат қоидалари."},{"y": "para","x": "47.3. Бундай манбалар қўлланиладиган ҳуқуққа зид бўлмаган даражада ҳисобга олинади."},{"y": "article","x": "48-модда. Адолат ва виждон тамойиллари"},{"y": "para","x": "48.1. Трибунал низони қатъий ҳуқуқ нормалари эмас, балки адолат ва виждон тамойиллари асосида ҳал қилиши мумкин."},{"y": "para","x": "48.2. Бундай ваколат фақат тарафларнинг аниқ ва ёзма розилиги мавжуд бўлган тақдирда амалга оширилади."},{"y": "para","x": "48.3. Трибунал ҳар қандай ҳолатда тарафларнинг қонуний ҳуқуқ ва манфаатларини ҳимоя қилиши шарт."},{"y": "chapter","x": "XI БОБ. АРБИТРАЖ ҚАРОРИ"},{"y": "article","x": "49-модда. Муҳокаманинг якунланиши"},{"y": "para","x": "49.1. Трибунал иш бўйича барча далиллар ва тушунтиришлар олинган деб ҳисоблаганда муҳокамани якунланган деб эълон қилади."},{"y": "para","x": "49.2. Муҳокама якунланганидан кейин янги далиллар фақат Трибунал рухсати билан қабул қилиниши мумкин."},{"y": "para","x": "49.3. Трибунал муҳокамани қайта очиш ҳуқуқига эга."},{"y": "article","x": "50-модда. Арбитраж қарорининг шакли"},{"y": "para","x": "50.1. Арбитраж қарори ёзма шаклда қабул қилинади."},{"y": "para","x": "50.2. Қарор сабаблантирилган бўлиши лозим, агар тарафлар бошқача келишмаган бўлсалар."},{"y": "para","x": "50.3. Қарор арбитр ёки арбитрлар томонидан имзоланади."},{"y": "para","x": "50.4. Уч нафар арбитр иштирок этган ҳолда қарор кўпчилик овоз билан қабул қилинади."},{"y": "para","x": "50.5. Арбитрлардан бири имзо қўймаган тақдирда бу ҳолат қарорда кўрсатилади."},{"y": "article","x": "51-модда. Арбитраж қарорининг мазмуни"},{"y": "para","x": "51.1. Арбитраж қарорида қуйидагилар кўрсатилиши лозим:"},{"y": "para","x": "а) арбитраж ишининг рақами;"},{"y": "para","x": "б) қарор қабул қилинган сана;"},{"y": "para","x": "в) арбитраж жойи;"},{"y": "para","x": "г) тарафларнинг номи ва реквизитлари;"},{"y": "para","x": "д) арбитрлар таркиби;"},{"y": "para","x": "е) талаблар ва эътирозлар;"},{"y": "para","x": "ж) ишнинг ҳолатлари;"},{"y": "para","x": "з) ҳуқуқий асослар;"},{"y": "para","x": "и) Трибунал хулосалари;"},{"y": "para","x": "к) қарор қисми;"},{"y": "para","x": "л) харажатлар тақсимоти."},{"y": "article","x": "52-модда. Арбитраж қарорларини ҳуқуқий экспертизадан ўтказиш"},{"y": "para","x": "52.1. Арбитраж қарори лойиҳаси имзоланишидан олдин Арбитраж Суди томонидан ҳуқуқий экспертизадан ўтказилиши мумкин."},{"y": "para","x": "52.2. Экспертизанинг мақсади:"},{"y": "para","x": "- процессуал камчиликларни аниқлаш;"},{"y": "para","x": "- қарор шаклини текшириш;"},{"y": "para","x": "- қарорнинг ижро этилиш имкониятини ошириш;"},{"y": "para","x": "- техник хатоларни бартараф қилиш."},{"y": "para","x": "52.3. Экспертиза Трибуналнинг мустақиллигига аралашиш ҳисобланмайди."},{"y": "para","x": "52.4. Арбитраж қарори мазмуни бўйича якуний қарор қабул қилиш ваколати Трибуналга тегишли."},{"y": "article","x": "53-модда. Қарор қабул қилиш муддати"},{"y": "para","x": "53.1. Арбитраж қарори муҳокама якунланганидан кейин мумкин қадар тез қабул қилиниши лозим."},{"y": "para","x": "53.2. Арбитраж Кенгаши ишнинг мураккаблигидан келиб чиқиб қарор қабул қилиш муддатини белгилаши мумкин."},{"y": "article","x": "54-модда. Қарорни тузатиш"},{"y": "para","x": "54.1. Тараф қарор қабул қилинган кундан бошлаб 30 кун ичида:"},{"y": "para","x": "- арифметик хатоларни;"},{"y": "para","x": "- техник хатоларни;"},{"y": "para","x": "- ёзув хатоларини тузатишни сўраб мурожаат қилиши мумкин."},{"y": "para","x": "54.2. Трибунал ўз ташаббуси билан ҳам бундай хатоларни тузатиши мумкин."},{"y": "article","x": "55-модда. Қўшимча қарор"},{"y": "para","x": "55.1. Агар Трибунал талаблардан бирини ҳал қилмаган бўлса, тараф қўшимча қарор чиқаришни сўраб мурожаат қилиши мумкин."},{"y": "para","x": "55.2. Бундай мурожаат қарор олинган кундан бошлаб 30 кун ичида берилади."},{"y": "para","x": "55.3. Қўшимча қарор арбитраж қарорининг ажралмас қисми ҳисобланади."},{"y": "article","x": "56-модда. Ярашув асосидаги қарор"},{"y": "para","x": "56.1. Тарафлар ярашувга эришган тақдирда Трибунал уларнинг илтимосига кўра келишилган шартлар асосида қарор қабул қилиши мумкин."},{"y": "para","x": "56.2. Бундай қарор одатдаги арбитраж қарори билан бир хил юридик кучга эга бўлади."},{"y": "chapter","x": "XII БОБ. АРБИТРАЖ ХАРАЖАТЛАРИ"},{"y": "article","x": "57-модда. Арбитраж харажатлари"},{"y": "para","x": "57.1. Арбитраж харажатлари таркибига қуйидагилар киради:"},{"y": "para","x": "- арбитраж йиғими;"},{"y": "para","x": "- арбитрлар гонорари;"},{"y": "para","x": "- маъмурий харажатлар;"},{"y": "para","x": "- экспертлар хизмати;"},{"y": "para","x": "- таржимонлар хизмати;"},{"y": "para","x": "- эшитув харажатлари;"},{"y": "para","x": "- бошқа зарур харажатлар."},{"y": "para","x": "57.2. Арбитраж харажатлари Арбитраж Суди томонидан тасдиқланган Тарифлар асосида ҳисобланади."},{"y": "article","x": "58-модда. Арбитрлар гонорари"},{"y": "para","x": "58.1. Арбитрлар ўз вазифаларини бажарганликлари учун ҳақ оладилар."},{"y": "para","x": "58.2. Гонорарни белгилашда қуйидагилар ҳисобга олинади:"},{"y": "para","x": "- даъво баҳоси;"},{"y": "para","x": "- ишнинг мураккаблиги;"},{"y": "para","x": "- муҳокама давомийлиги;"},{"y": "para","x": "- сарфланган меҳнат ҳажми."},{"y": "article","x": "59-модда. Депозитлар"},{"y": "para","x": "59.1. Арбитраж муҳокамаси харажатларини қоплаш учун тарафлардан депозит тўлаш талаб қилиниши мумкин."},{"y": "para","x": "59.2. Котибият депозит миқдорини белгилайди."},{"y": "para","x": "59.3. Депозит белгиланган муддатда тўланмаган тақдирда:"},{"y": "para","x": "- иш юритиш тўхтатиб турилиши;"},{"y": "para","x": "- қарши даъво кўриб чиқилмаслиги;"},{"y": "para","x": "- ариза қайтарилиши мумкин."},{"y": "article","x": "60-модда. Харажатларни тақсимлаш"},{"y": "para","x": "60.1. Трибунал арбитраж харажатларини тарафлар ўртасида тақсимлайди."},{"y": "para","x": "60.2. Харажатларни тақсимлашда қуйидагилар ҳисобга олинади:"},{"y": "para","x": "- иш натижаси;"},{"y": "para","x": "- тарафларнинг процессуал хулқи;"},{"y": "para","x": "- талабларнинг қаноатлантирилиш даражаси."},{"y": "para","x": "60.3. Трибунал оқилона юридик харажатларни ҳам ундириш тўғрисида қарор қабул қилиши мумкин."},{"y": "chapter","x": "XIII БОБ. МАХФИЙЛИК ВА КИБЕРХАВФСИЗЛИК"},{"y": "article","x": "61-модда. Махфийлик"},{"y": "para","x": "61.1. Арбитраж муҳокамаси махфий ҳисобланади."},{"y": "para","x": "61.2. Тарафлар, арбитрлар, экспертлар, таржимонлар, Котибият ходимлари ва муҳокамада иштирок этувчи бошқа шахслар иш бўйича маълумотларни махфий сақлашлари шарт."},{"y": "para","x": "61.3. Қуйидагилар махфий маълумотлар ҳисобланади:"},{"y": "para","x": "а) даъво материаллари;"},{"y": "para","x": "б) жавоб ва қарши даъволар;"},{"y": "para","x": "в) далиллар;"},{"y": "para","x": "г) гувоҳ кўрсатмалари;"},{"y": "para","x": "д) эксперт хулосалари;"},{"y": "para","x": "е) процессуал буйруқлар;"},{"y": "para","x": "ж) арбитраж қарорлари;"},{"y": "para","x": "з) муҳокама жараёнида олинган бошқа маълумотлар."},{"y": "para","x": "61.4. Қуйидаги ҳолларда маълумотларни ошкор қилишга йўл қўйилади:"},{"y": "para","x": "а) тарафларнинг ёзма розилиги мавжуд бўлса;"},{"y": "para","x": "б) қонунчилик талаб қилса;"},{"y": "para","x": "в) қарорни тан олиш ёки ижро этиш учун зарур бўлса;"},{"y": "para","x": "г) давлат органлари қонуний талаб қилганда."},{"y": "para","x": "61.5. Арбитраж Суди илмий ва статистик мақсадларда арбитраж ишларига оид маълумотларни тарафларни идентификация қилиш имконини бермайдиган шаклда эълон қилиши мумкин."},{"y": "article","x": "62-модда. Шахсий маълумотларни ҳимоя қилиш"},{"y": "para","x": "62.1. Арбитраж муҳокамаси давомида олинган шахсий маълумотлар қонунчилик ва халқаро стандартларга мувофиқ ҳимоя қилинади."},{"y": "para","x": "62.2. Арбитраж Суди шахсий маълумотларни фақат арбитраж муҳокамасини амалга ошириш мақсадларида қайта ишлайди."},{"y": "para","x": "62.3. Тарафлар тақдим этган маълумотларнинг қонунийлигини таъминлаш учун жавобгар ҳисобланадилар."},{"y": "para","x": "62.4. Котибият шахсий маълумотларни сақлаш ва ҳимоя қилиш бўйича ички тартибларни жорий этади."},{"y": "article","x": "63-модда. Киберхавфсизлик"},{"y": "para","x": "63.1. Арбитраж Суди электрон маълумотларнинг хавфсизлигини таъминлаш чораларини кўради."},{"y": "para","x": "63.2. Трибунал ишнинг хусусиятидан келиб чиқиб Киберхавфсизлик протоколини қабул қилиши мумкин."},{"y": "para","x": "63.3. Тарафлар қуйидаги талабларга риоя қилишлари лозим:"},{"y": "para","x": "а) хавфсиз электрон алоқа воситаларидан фойдаланиш;"},{"y": "para","x": "б) махфий маълумотларни ҳимоя қилиш;"},{"y": "para","x": "в) электрон далилларнинг бутлигини таъминлаш."},{"y": "para","x": "63.4. Киберхавфсизлик билан боғлиқ хавфлар аниқланган тақдирда Трибунал қўшимча муҳофаза чораларини белгилаши мумкин."},{"y": "chapter","x": "XIV БОБ. ЯКУНИЙ ҚОИДАЛАР"},{"y": "article","x": "64-модда. Регламентни талқин қилиш"},{"y": "para","x": "64.1. Ушбу Регламентни қўллаш ва талқин қилиш билан боғлиқ масалалар Арбитраж Суди томонидан ҳал қилинади."},{"y": "para","x": "64.2. Регламент халқаро арбитражнинг умумэътироф этилган тамойиллари ҳисобга олинган ҳолда талқин қилинади."},{"y": "para","x": "64.3. Регламентнинг турли тиллардаги матнлари ўртасида тафовут юзага келган тақдирда ўзбек тилидаги матн устувор ҳисобланади, агар Арбитраж Суди бошқача қарор қабул қилмаган бўлса."},{"y": "article","x": "65-модда. Регламентда назарда тутилмаган масалалар"},{"y": "para","x": "65.1. Ушбу Регламентда бевосита тартибга солинмаган процессуал масалалар Трибунал томонидан ҳал қилинади."},{"y": "para","x": "65.2. Бундай қарорлар қабул қилинишида қуйидагилар ҳисобга олинади:"},{"y": "para","x": "- тарафлар автономияси;"},{"y": "para","x": "- тенглик тамойили;"},{"y": "para","x": "- адолатли муҳокама ҳуқуқи;"},{"y": "para","x": "- процессуал самарадорлик;"},{"y": "para","x": "- халқаро арбитраж амалиёти."},{"y": "para","x": "65.3. Зарур ҳолларда Трибунал халқаро арбитраж институтларининг илғор амалиётидан фойдаланиши мумкин."},{"y": "article","x": "66-модда. Жавобгарликдан озод қилиш"},{"y": "para","x": "66.1. Арбитрлар, Арбитраж Кенгаши аъзолари, Арбитраж Суди Раиси, Котибият ходимлари ва экспертлар ўз вазифаларини виждонан бажариш чоғида содир этилган ҳаракатлар ёки ҳаракатсизлик учун жавобгар бўлмайдилар, қасддан ҳуқуқбузарлик ёки қўпол эҳтиётсизлик ҳолатлари бундан мустасно."},{"y": "para","x": "66.2. Мазкур модда қонунчиликда назарда тутилган жавобгарлик чораларини истисно қилмайди."},{"y": "article","x": "67-модда. Регламентга ўзгартириш ва қўшимчалар киритиш"},{"y": "para","x": "67.1. Ушбу Регламентга ўзгартириш ва қўшимчалар Ўзбекистон Халқаро Арбитраж Судлари Бирлашмасининг Бошқарув қарори билан киритилади."},{"y": "para","x": "67.2. Ўзгартириш ва қўшимчаларда уларнинг кучга кириш санаси кўрсатилади."},{"y": "para","x": "67.3. Агар тарафлар бошқача келишмаган бўлсалар, иш бошланган пайтда амалда бўлган Регламент таҳрири қўлланилади."},{"y": "article","x": "68-модда. Кучга кириши"},{"y": "para","x": "68.1. Ушбу Арбитраж Регламенти тасдиқланган кундан эътиборан кучга киради."},{"y": "para","x": "68.2. Регламент кучга кирган пайтдан бошлаб мазкур Арбитраж Суди томонидан кўриб чиқиладиган барча ишларга нисбатан қўлланилади."},{"y": "para","x": "68.3. Регламент расмий веб-сайтда ва Арбитраж Суди ахборот ресурсларида эълон қилиниши мумкин."}],"ustav": [{"y": "heading","x": "ЎЗБЕКИСТОН ХАҚАРО АРБИТРАЖ СУДЛАРИ  БИРЛАШМАСИНИНГ"},{"y": "heading","x": "УСТАВИ"},{"y": "para","x": "Тошкент 2021 йил"},{"y": "para","x": "1. АСОСИЙ  ҚОИДАЛАР"},{"y": "para","x": "1.1. Ўзбекистон Халқаро Арбитраж Судлари БИРЛАШМАСИ Ўзбекистон Републикаси Адлия   Вазирлиги томонидан 2021 йил “22” июнь куни  992- сон билан    давлат рўйхатига олинган."},{"y": "para","x": "1.2. Ўзбекистон Халқаро Арбитраж Судлари БИРЛАШМАСИ (бундан буён «БИРЛАШМА» деб юритилади) Ўзбекистон Республикасида халқаро            арбитраж судларини ташкил этиш ва ривожлантиришда кўмаклашиш,                                Республикада фаолият юритаётган халқаро арбитраж судларини қўллаб-қувватлаш, уларнинг ҳуқуқларини ҳимоя қилиш мақсадида жамоат бирлашмаси шаклида ташкил этилган нодавлат нотижорат ташкилотдир."},{"y": "para","x": "Ташкилий ҳуқуқий шакли – жамоат бирлашмаси."},{"y": "para","x": "Ташкилотнинг тури – Республикага оид жамоат ташкилот."},{"y": "para","x": "-Бирлашманинг ўзбек тилидаги тўлиқ номи Ўзбекистон Халқаро Арбитраж Судлари БИРЛАШМАСИ;"},{"y": "para","x": "- қисқартирилган номи – ЎзХАСБ;"},{"y": "para","x": "- инглиз тилидаги тўлиқ номи «THE UNION OF INTERNATIONAL ARBITRATION COURTS OF UZBEKISTAN»;"},{"y": "para","x": "- қисқартирилган номи – AIACU;"},{"y": "para","x": "-рус тилида «ОБЪЕДИНЕНИЕ МЕЖДУНАРОДНЫХ АРБИТРАЖНЫХ   СУДОВ УЗБЕКИСТАНА»;"},{"y": "para","x": "- қисқартирилган номи – ОМАСУз;"},{"y": "para","x": "1.3. Бирлашма ўз фаолиятини Ўзбекистон Республикаси Конституцияси, Ўзбекистон Республикасининг «Нодавлат нотижорат ташкилотлари тўғрисида»ги, «Ўзбекистон Республикасида жамоат бирлашмалари тўғрисида”ги қонунлари ва бошқа қонун ҳужжатлари ҳамда ушбу Устав асосида амалга оширади."},{"y": "para","x": "1.4. Бирлашма ўзига юклатилган вазифа ва функцияларни самарали амалга ошириш учун Қорақалпоғистон Республикаси, Тошкент шаҳрида Бош филиаллар,  вилоятларда  ҳудудий филиалларини ташкил этади."},{"y": "para","x": "Бирлашма Қорақалпоғистон Республикаси ва Тошкент шаҳрида 2 та Бош филиал ва 12 та вилоятда ташкил этилган филиаллари ҳамда уларнинг ҳузуридаги доимий фаолият кўрсатувчи  Халқаро Арбитраж Судлари билан бирга ягона тизимни ташкил этади."},{"y": "para","x": "Бирлашманинг ҳудудий Бош филиал ва филиаллари юридик шахс мақомига эга."},{"y": "para","x": "1.5. Бирлашма юридик шахс ҳисобланади ва ўз тасарруфида бўлган мол-мулкка эгалик қилади. Бирлашма Ўзбекистон Республикаси ҳудудидаги банкларда ҳисоб рақамлари очиш (шу жумладан валюта хисоб рақами), шартнома ва битимлар тузиш, шунингдек ўз Уставида кўрсатилган вазифаларни бажариш мақсадида хўжалик тадбиркорлик фаолияти билан шуғулланиш ҳуқуқига эга."},{"y": "para","x": "Бирлашма ўз номидан мулкий ва шахсий номулкий ҳуқуқларга эга бўлиши ва мажбуриятлар олиши, ваколатли судларда даъвогар ва жавобгар бўлиши мумкин."},{"y": "para","x": "Бирлашма ўзига олган мажбуриятлар бўйича амалдаги қонунчиликка мувофиқ фақат ўз тасарруфидаги мол-мулки билан жавоб беради."},{"y": "para","x": "Давлат ва унинг органлари Бирлашма мажбуриятлари юзасидан жавоб бермайди, худди шундай Бирлашма ҳам давлат ва унинг органлари мажбуриятлари юзасидан жавоб бермайди."},{"y": "para","x": "1.6. Бирлашма белгиланган тартибда рўйҳатдан ўтказилган, ўзининг номи ёзилган думалоқ муҳрга, Бирлашма тизими учун умумий бўлган байроқ, рамз, расмий идора варақаси ва штампларига эга бўлиши мумкин."},{"y": "para","x": "Бирлашманинг фаолият муддати чекланмаган."},{"y": "para","x": "Бирлашманинг доимий фаолият кўрсатувчи раҳбар органлари манзили: Тошкент шаҳри, Яшнобод тумани, Паркент кўчаси, №30 “в”-уй, ИНД:100007."},{"y": "para","x": "Бирлашма Ўзбекистон Республикаси ҳудудида фаолият кўрсатади."},{"y": "para","x": "2. БИРЛАШМАНИНГ МАҚСАД, ВАЗИФА ВА МАЖБУРИЯТЛАРИ"},{"y": "para","x": "2.1 Бирлашма фаолиятининг асосий мақсади  Ўзбекистон Республикасида Халқаро Арбитраж Судларини ташкил этиш ва ривожлантиришга кўмаклашиш, республикада фаолият юритаётган Халқаро Арбитраж Судларини қўллаб-қувватлаш, ўз тизимидаги Халқаро Арбитраж Судлари ва аъзоларининг ҳуқуқларини ҳимоя қилишдан иборат."},{"y": "para","x": "2.2. Бирлашма қуйидаги вазифаларни бажаради:"},{"y": "para","x": "- Халқаро Арбитраж Судларини ташкил этишда кўмаклашиш, Халқаро Арбитраж Судларини ривожлантириш;"},{"y": "para","x": "- Бирлашманинг таркибидаги Халқаро Арбитраж Судларини ҳамда Бирлашма аъзоларининг ҳуқуқ ва манфаатларини ҳимоя қилиш;"},{"y": "para","x": "- Бирлашманинг  аъзоларига тегишли тартибда юридик маслаҳатлар бериш,  юридик ёрдам кўрсатиш ва уларни ижтимоий ҳимоя қилиш;"},{"y": "para","x": "- Бирлашма таркибидаги Бош филиал ва филиаллар ҳузуридаги доимий фаолият кўрсатувчи халқаро ҳакамлик судларини соҳага оид керакли адабиётлар билан таъминлаш;"},{"y": "para","x": "- Ўзбекистон Республикаси қонунчилигига зид бўлмаган бошқа вазифаларни амалга оширади."},{"y": "para","x": "2.3. Бирлашма:"},{"y": "para","x": "- қонун талаблари ва норматив-ҳуқуқий ҳужжатларга риоя этиш;"},{"y": "para","x": "- ўз мол-мулки ва пул маблағларидан фойдаланиш тўғрисидаги ахборот билан ўрнатилган тартибда танишиш эркинлигини таъминлаш;"},{"y": "para","x": "- Ўзбекистон Республикаси Адлия Вазирлигига ўзи ўтказаётган тадбирлари тўғрисида белгиланган тартибда ҳабар бериш;"},{"y": "para","x": "- рўйҳатдан ўтказувчи солиқ ва статистика органларига ўз фаолияти тўғрисида ҳисоботлар тақдим этиш мажбуриятларига эга;"},{"y": "para","x": "-   лицензия талаб этиладиган фаолият турлари бўйича лицензия олгандан сўнг ўз фаолиятини амалга оширади."},{"y": "para","x": "- БИРЛАШМА ҲУҚУҚЛАРИ"},{"y": "para","x": "3.1. Бирлашма қуйидаги ҳуқуқларга эга:"},{"y": "para","x": "- нодавлат нотижорат ташкилотлар ва ижтимоий ҳаётнинг турли масалаларига доир ташаббуслар билан чиқиш, давлат ҳокимияти органларига халқаро ҳакамлик судларини ривожлантириш юзасидан белгиланган тартибда таклифлар киритиш;"},{"y": "para","x": "- давлат ҳокимияти органларининг қарорларини ишлаб чиқишда қонун ҳужжатларида назарда тутилган тартибда иштирок этиш;"},{"y": "para","x": "-  Халқаро Арбитраж Судлари фаолиятига дахлдор қонун лойиҳалари ҳамда бошқа норматив-ҳуқуқий ҳужжатларни ишлаб чиқишда ва муҳокама қилишда қонун ҳужжатларида белгиланган тартибда  қатнашиш;"},{"y": "para","x": "- ваколатли судлар билан ҳамкорликда ўқув илмий услубий семинар, конференция ва давра суҳбатлари ташкил этиш;"},{"y": "para","x": "- Халқаро Арбитраж Судларига оид қонунчиликни такомиллаштириш юзасидан ваколатли судлар билан ўзаро фикр алмашиш;"},{"y": "para","x": "-  ваколати доирасида ўз таркибидаги Бош филиал ва филиаллар ҳузуридаги Халқаро Арбитраж Судлари манфаатларига дахлдор масалалар бўйича идоралар, идоралараро ва бошқа комиссиялар, шунингдек, эксперт кенгашлари ҳамда бошқа  ташкилотларнинг тадбирларида иштирок этиш;"},{"y": "para","x": "-  Халқаро Арбитраж Судлари ва Бирлашма аъзоларига ахборот таъминоти,  юридик ҳамда консультатив ёрдам бериш;"},{"y": "para","x": "- Бирлашмага юклатилган вазифа ва функцияларни бажариш зарурияти юзасидан давлат ҳокимияти ва бошқаруви органларидан ахборотлар олиш;"},{"y": "para","x": "- замонавий талаб ва стандартлардан келиб чиқиб, Халқаро Арбитраж Судлари судьялигига номзодларни тайёрлаш ва Халқаро Арбитраж Судлари  судьяларининг малакасини оширишни белгиланган тартибда  ташкил этиш:"},{"y": "para","x": "- Ўзбекистон Республикаси қонунчилигига риоя этган ҳолда корхоналар ташкил этиш, ўз Бош филиал ва филиалларини очиш;"},{"y": "para","x": "- тегишли давлат хокимияти идоралари орқали чет эл халқаро арбитраж институтлари билан муносабатларни ўрнатиш, Ўзбекистон Республикасида фаолият олиб бораётган хорижий мамлакатларнинг ва халқаро ташкилотларнинг тегишли ваколатхоналаридан Халқаро Арбитраж Судлари фаолиятини ривожлантиришга оид грант, хомийлик ва бошқа маблағларни белгиланган тартибда  олиш ва улар билан тегишли шартномалар тузиш;"},{"y": "para","x": "- ўз фаолияти тўғрисида ахборот тарқатиш;"},{"y": "para","x": "- оммавий ахборот воситаларини таъсис этиш ҳамда белгиланган тартибда ноширлик фаолиятини амалга ошириш;"},{"y": "para","x": "-  ўз рамзий белгиларини таъсис этиш;"},{"y": "para","x": "-  халқаро ҳакамлик судларини қўллаб-қувватловчи фондлар таъсис этиш;"},{"y": "para","x": "-  қонунчиликка мувофиқ Халқаро Арбитраж Судларини ташкил қилиш;"},{"y": "para","x": "-  халқаро арбитраж муҳокамасига оид конференциялар, учрашувлар, семинар-тренинг ва бошқа тадбирларни ташкил этиш ҳамда ўтказиш, белгиланган тартибда  нашриёт ва реклама ҳизматини кўрсатиш;"},{"y": "para","x": "- мустақил тарзда ўзининг таркибий тузилишини белгилаш, штатлар жадвали, ходимлар сони, меҳнатга ҳақ тўлаш ва рағбатлантириш тартиби ва шаклларини белгилаш;"},{"y": "para","x": "- Уставда белгиланган вазифаларни бажариш учун тадбиркорлик ва консалтинг, медиация ҳамда бошқа тузилмаларини,  ташкил этиш;"},{"y": "para","x": "- нодавлат нотижорат ташкилоти сифатида қонун ҳужжатларида назарда тутилган бошқа ҳуқуқларга ҳам эга бўлиш."},{"y": "para","x": "3.2. Бирлашма тизимига раҳбарлик қилишда қуйидаги ҳуқуқларга эга:"},{"y": "para","x": "- Бирлашманинг ҳудудий Бош филиал ва филиалларини ҳамда бошқа таркибий тузилмаларини, шу жумладан тадбиркорлик субъектларини ва консалтинг, медиация хизмати марказларини ташкил этиш, қайта ташкил этиш ва уларни тугатиш;"},{"y": "para","x": "- Бирлашма томонидан ташкил этилган ҳудудий Бош филиал ва филиаллари ҳамда бошқа таркибий тузилмалари, шу жумладан тадбиркорлик субъектлари учун ижро этиши мажбурий бўлган хужжатлар (қарор, фармойиш, буйруқ, низом, тартиб ва ҳ.к.)ни қабул қилиш;"},{"y": "para","x": "- Бирлашманинг ҳудудий Бош филиал ва филиаллари томонидан қабул қилинган амалдаги қонунчиликка ва мазкур Уставга зид бўлган қарор ва буйруқларини бекор қилиш;"},{"y": "para","x": "- Бирлашма, унинг ҳудудий Бош филиал ва филиаллари ҳузурида доимий фаолият кўрсатувчи Халқаро Арбитраж Судлари фаолиятини мониторинг қилиш, улардаги иш юритувини такомиллаштириш мақсадида тегишли тавсиялар ва методик кўрсатмалар ишлаб чиқиш;"},{"y": "para","x": "- Халқаро Арбитраж Судлари томонидан суд йиғимларини ундирилишининг қонунийлигини ўрганиш, лозим бўлганда арбитраж муҳокамасига тааллуқли иш материаллари билан танишиб чиқиш ва тавсиялар бериш, чиқарилаётган ажрим ва ҳал қилув қарорларининг қонунийлигини талаб қилиш, ишни кўришда қонун бузилиш ҳолатлари аниқланган тақдирда ваколатли органларга хабар қилиш, қонун бузилиш ҳолларига йўл қўйган халқаро арбитраж судлари судьяларига нисбатан ўз ваколати доирасида тегишли жавобгарлик чораларини кўриш;"},{"y": "para","x": "- Бирлашманинг ҳудудий Бош филиал ва филиаллари ҳамда бошқа таркибий тузилмаларининг, шу жумладан ўзи ташкил этган тадбиркорлик субъектларининг молиявий - хўжалик фаолиятини текшириш ва тафтиш қилиш;"},{"y": "para","x": "- амалдаги қонунчиликка зид бўлмаган бошқа ваколатларни амалга ошириш."},{"y": "para","x": "- БИРЛАШМА  АЪЗОЛИГИГА  ҚАБУЛ  ҚИЛИШ"},{"y": "heading","x": "ВА  АЪЗОЛИКДАН  ЧИҚИШ"},{"y": "para","x": "4.1. Бирлашмага аъзо бўлиш."},{"y": "para","x": "Бирлашмага 18 ёшга тўлган, ушбу Устав ҳамда Бирлашманинг бошқа ички меъёрий ҳужжатларини тан олган жисмоний шахслар (фуқаролар, чет эл фуқаролари ва фуқаролиги бўлмаган шахслар) якка тартибда аъзо бўла олади."},{"y": "para","x": "4.2. Бирлашманинг аъзолигига қабул қилиш жисмоний шахснинг аризасига кўра тегишли тартибда бевосита Бирлашма Раиси, таркибий тузилмалари ёки ҳудудий Бош филиал ва филиаллар раҳбарлари томонидан берилган тавсияномаларига асосан Бирлашма Бошқарувининг қарори асосида амалга оширилади."},{"y": "para","x": "4.3. Бирлашма аъзолигига қабул қилиш ва аъзоликдан чиқиш масалалари Бирлашма Бошқаруви томонидан амалга оширилади."},{"y": "para","x": "4.4. Аъзоларнинг ҳисоби Бирлашма ва унинг бўлинмалари томонидан олиб борилади."},{"y": "para","x": "4.5. Бирлашма аъзолари ўз аризасига кўра ёки қонун ҳужжатлари ва мазкур Устав талабларини бузганда бошқарув қарорига кўра аъзоликдан чиқарилиши мумкин."},{"y": "para","x": "5. БИРЛАШМА АЪЗОЛАРИНИНГ ҲУҚУҚ ВА МАЖБУРИЯТЛАРИ"},{"y": "para","x": "5.1. Бирлашма аъзолари қуйидаги ҳуқуқларга эга:"},{"y": "para","x": "-    Бирлашма томонидан ўтказиладиган тадбирларда иштирок этиш;"},{"y": "para","x": "- Бирлашманинг барча раҳбарлик органларига сайлаш ва сайланиш ҳуқуқидан ўрнатилган тартиб асосида фойдаланиш;"},{"y": "para","x": "-  Бирлашма ва унинг ҳудудий таркибий тузилмаларидан уларнинг ваколат доирасига кирадиган масалаларни ҳал этишда ёрдам олиш;"},{"y": "para","x": "-  шартнома асосида Бирлашма, унинг ҳудудий таркибий тузилмалари, улар томонидан ташкил этилган корхоналар ва ташкилотлар хизматидан ҳамда Бирлашманинг рамзий белгисидан фойдаланиш;"},{"y": "para","x": "- илмий - тадқиқот ва ҳуқуқ - тарғибот ишларини ташкил этиш билан боғлиқ турли тадбирларни ўтказишда ҳомийлик қилиш ва ёрдам олиш;"},{"y": "para","x": "- Бирлашма аъзолигидан исталган вақтда ва белгиланган тартибда чиқиш."},{"y": "para","x": "5.2. Ваколатга эга бўлган вакиллари орқали қуйидаги ҳуқуқларга эга:"},{"y": "para","x": "- Бирлашма фаолияти тўғрисида белгиланган тартибда маълумотлар олиш;"},{"y": "para","x": "- Бирлашма томонидан ўтказиладиган Умумий йиғилишга ўз вакилларини сайлаш;"},{"y": "para","x": "- Бирлашма Бошқарувига, унинг ҳудудий таркибий тузилмалари раҳбар органларига Бирлашма фаолиятига доир фикр ва таклифларини тақдим этиш:"},{"y": "para","x": "- Бирлашманинг ички меъёрий ҳужжатларида кўрсатилган бошқа ҳуқуқлардан фойдаланиш."},{"y": "para","x": "5.3. Бирлашма аъзоларининг мажбуриятлари қуйидагилардан иборат:"},{"y": "para","x": "- Бирлашма Устави ва бошқа ички меъёрий хужжатларига оғишмай риоя қилиш;"},{"y": "para","x": "- Бирлашма ва унинг ҳудудий таркибий тузилмалари раҳбар органларининг қарорларини ўз вақтида бажариш."},{"y": "para","x": "- ўз фаолиятини қонунийлик, холислик, ҳалоллик ва адолат мезонлари асосида амалга ошириш;"},{"y": "para","x": "- Бирлашманинг мақсад ва вазифаларини амалга оширишда фаол кўмаклашиш;"},{"y": "para","x": "- Бирлашма ва унинг тегишли худудий таркибий тузилмалари томонидан ўтказилаётган тадбирларда фаол иштирок этиш,"},{"y": "para","x": "6. БИРЛАШМАНИНГ  МОЛ-МУЛКИ,  ДАРОМАД  МАНБАЪЛАРИ ВА  УЛАРДАН  ФОЙДАЛАНИШ  ТАРТИБИ"},{"y": "para","x": "6.1. Бирлашма ўзига мулк ҳуқуқи асосида тегишли бўлган мол-мулк: жумладан, бинолар, иншоатлар, транспорт воситалари, ускуналар, акциялар ва бошқа қимматбаҳо қоғозлар, пул маблағлари (чет эл валютаси), шунингдек, интеллектуал мулк объектларига эгалик қилади."},{"y": "para","x": "6.2. Бирлашма ва унинг филиалларининг мол-мулки ва даромад манбаълари қуйидагилардан иборат:"},{"y": "para","x": "- ихтиёрий равишда ўтказилган пул ва ҳайрия маблағлари;"},{"y": "para","x": "- Уставга мувофиқ ўтказилган лекция, кўргазма, семинар ҳамда бошқа тадбирлардан тушган тушумлари;"},{"y": "para","x": "- Бош филиал ва филиаллар, ҳамда ўз ҳузуридаги доимий фаолият кўрсатувчи Халқаро Арбитраж Судига келиб тушган йиғимларидан ажратмалар;"},{"y": "para","x": "- хўжалик ва тадбиркорлик фаолиятидан тушадиган даромадлар;"},{"y": "para","x": "- Бирлашма таъсис этган корхоналар томонидан ажратилган маблағлар;"},{"y": "para","x": "- белгиланган тартибда ажратилган грантлар, субсидиялар, хомийлик маблағлари ва давлат ижтимоий буюртмаларини бажаришдан келиб тушадиган маблағлар;"},{"y": "para","x": "- белгиланган тартибда ташкил этилган ноширлик фаолиятидан келиб тушадиган маблағлар;"},{"y": "para","x": "- амалдаги қонун ҳужжатларида тақиқланмаган бошқа тушумлар."},{"y": "para","x": "6.3. Бирлашманинг ҳудудий таркибий тузилмалари мулкини бошқариш, уларни ташкил этиш ва тугатиш  тартиби ҳамда уларнинг ҳуқуқ ва мажбуриятлари Бирлашма Бошқаруви томонидан тасдиқланадиган Низомида белгиланади."},{"y": "para","x": "6.4. Бирлашманинг Уставида кўрсатилган фаолиятини таъминлаш ва кўзда тутилмаган харажатларни қоплаш, шартнома ва бошқа мажбуриятларни ўз вақтида ва сифатли бажариш учун жамғармалар ташкил этиши мумкин, уларнинг миқдори ва фойдаланиш тартиби Бирлашма Бошқаруви томонидан белгиланади."},{"y": "para","x": "- БИРЛАШМА  РАҲБАР  ОРГАНЛАРИ  (РАҲБАРИ)"},{"y": "para","x": "7.1. Бирлашманинг раҳбар органлари қуйидагилар ҳисобланади:"},{"y": "para","x": "- Ўзбекистон Халқаро Арбитраж Судлари Бирлашма  аъзоларининг Умумий йиғилиши;"},{"y": "para","x": "- Ўзбекистон Халқаро Арбитраж Судлари Бирлашмаси Бошқаруви;"},{"y": "para","x": "- Бирлашма раиси."},{"y": "para","x": "7.2. Бирлашманинг юқори органи Ўзбекистон Халқаро Арбитраж Судлари Бирлашмаси аъзоларининг Умумий йиғилиши (қуйида «Умумий йиғилиш» деб юритилади) ҳисобланиб, унинг мутлақ ваколатлари қуйидагилардан иборат:"},{"y": "para","x": "- Бирлашма ва унинг ҳудудий таркибий тузилмаларининг истиқболдаги фаолиятининг асосий йўналишларини белгилаб бериш;"},{"y": "para","x": "- Бирлашма ва унинг ҳудудий-таркибий тузилмалари фаолияти тўғрисидаги ҳисобот-маърузаларни тинглаш, улар бўйича қарорлар қабул қилиш;"},{"y": "para","x": "- Бирлашма фаолиятини қайта ташкил этиш ва тугатиш билан боғлиқ масалаларни ҳал қилиш;"},{"y": "para","x": "- Бирлашма Бошқаруви аъзоларини сайлаш,"},{"y": "para","x": "- Бирлашма Тафтиш комиссияси аъзоларини сайлаш."},{"y": "para","x": "7.3. Умумий йиғилиш заруриятга қараб, лекин 5 (беш) йилда камида 2 марта чақирилади. Умумий йиғилиш аъзолардан ёки аъзоларнинг ваколатли вакилларидан иборат бўлади. Умумий йиғилиш ваколатли вакиллар орқали ўтказилганда,  ваколатли вакил (делегат)лар Бирлашма Умумий йиғилиши томонидан тасдиқланган Регламент асосида сайланадилар."},{"y": "para","x": "Умумий йиғилишга сайлаш ва сайланиш ҳуқуқи Бирлашма олдидаги ўз мажбуриятларини лозим даражада бажариб келаётган аъзоларга тегишли бўлади."},{"y": "para","x": "Умумий йиғилиш ўтказилиши (шу жумладан навбатдан ташқари), делегатлар сайлаш  тартиби ва делегатлар кворуми, кун тартиби, вақти ва жойи ҳақида Умумий йиғилиш чақирувчи томонидан йиғилиш ўтказилишидан камида бир ой олдин хабардор қилинади."},{"y": "para","x": "7.4. Умумий йиғилиш кун тартибида кўриладиган масалалар Бирлашма  Раиси, Бирлашма Бошқаруви, Тафтиш комиссияси ва Бирлашма аъзоларининг камида учдан икки қисмининг ёзма ташаббуси билан киритилиши мумкин."},{"y": "para","x": "7.5. Умумий йиғилиш Бирлашма Раиси, Бирлашма Бошқаруви, Тафтиш комиссияси ташаббуси, рўйхатдан ўтказувчи орган (зарурат туғилганда) ёки  аъзоларнинг камида учдан икки  қисми талаби билан  бир ой муддат олдин  чақирилиши мумкин."},{"y": "para","x": "7.6. Умумий йиғилишда белгиланган тартибда сайланган вакил(делегат)ларнинг камида учдан икки қисми қатнашган тақдирда, Умумий йиғилишни ўтказиш ваколатли ҳисобланади."},{"y": "para","x": "Умумий йиғилиш қарорлари, унда иштирок этаётган вакил (делегат)ларнинг кўпчилигининг  овози очиқ овоз бериш йўли билан қабул қилинади, Бирлашма фаолиятини тўхтатиш билан боғлиқ масалалар Умумий йиғилишда иштирок этувчиларнинг учдан икки қисмининг овози билан ҳал этилади."},{"y": "para","x": "Умумий йиғилиш ўз қарори билан айрим масалаларни ёпиқ (яширин) овоз бериш йўли билан ҳал этишни белгилаши ва ўзига тегишли мутлақ ваколатларнинг айримларини Бирлашма Бошқарувига бериши мумкин."},{"y": "para","x": "7.7. Умумий йиғилишлар оралиғида Бирлашма фаолиятига раҳбарлик қилиш Умумий йиғилиш томонидан 5 йил муддатга сайланган Бирлашма  Бошқаруви томонидан олиб борилади."},{"y": "para","x": "7.8. Бирлашма Бошқарувининг таркиби 5 (беш) нафардан иборат бўлиб, улар Бирлашма аъзолари орасидан 5 йил муддатга Умумий йиғилиш томонидан сайланади. Бирлашма Бошқаруви аъзолари ўзларининг орасидан Бошқарув раисини сайлайдилар. Бошқарув раиси бир вақтнинг ўзида Бирлашма раиси ҳисобланади."},{"y": "para","x": "7.9. Ўзбекистон Халқаро Арбитраж Судлари Бирлашмасининг Бошқаруви:"},{"y": "para","x": "- Умумий йиғилишлар оралиғида Бирлашма тизимининг асосий йўналишлари ва фаолияти шаклларини белгилайди;"},{"y": "para","x": "- Бирлашма Устави ва Умумий йиғилиш қарорларининг бажарилиши устидан назорат олиб боради;"},{"y": "para","x": "- Бирлашма томонидан тузилган шартномаларнинг ижро этилишини назорат қилиб боради;"},{"y": "para","x": "- кўчмас мулк ва унга тенглаштирилган (автомобил ва х.к) мол-мулкни тасарруф этиш масалалари буйича Умумий йиғилишга тайёрлайди;"},{"y": "para","x": "- худудий бўлинмаларини тузиш, қайта ташкил этиш ва тугатиш тўғрисида қарорлар қабул қилади;"},{"y": "para","x": "- Бирлашма ҳудудий тузилмалари тугрисидаги Низомни тасдиқлайди, уларга ўзгартириш ва қўшимчалар киритади;"},{"y": "para","x": "- Бирлашма фаолиятига оид бошқа масалаларни ҳал қилади."},{"y": "para","x": "7.10. Бошқарув йиғилиши заруриятга кўра, лекин ҳар олти ойда камида бир маротаба чақирилади. Йиғилишни Бошқарув раиси олиб боради. Йиғилиш Бошқарув аъзоларининг ярмидан кўпи иштирок этганда ваколатли ҳисобланади."},{"y": "para","x": "Бирлашма Бошқарувининг қарорлари унинг йиғилишида қатнашаётган аъзоларнинг оддий кўпчилик овози билан қабул қилинади. Овозлар тенг бўлганда, Бошқарув раисининг овози ҳал қилувчи ҳисобланади. Бошқарувнинг навбатдаги йиғилишида кўриладиган масалалар Бошқарув Раиси ёки унинг аъзолари ташаббуси билан киритилади."},{"y": "para","x": "7.11. Бирлашма раиси Бирлашманинг юқори мансабдор шахси ҳисобланиб у Бирлашма ва унинг тузилмаларининг кундалик фаолиятига раҳбарлик қилади. Бирлашма раиси ўзининг ўринбосарларига эга бўлади."},{"y": "para","x": "Бирлашма Раиси:"},{"y": "para","x": "- Бирлашма Бошқаруви фаолиятига бевосита раҳбарлик қилади;"},{"y": "para","x": "-Бирлашма Умумий йиғилиши ва Бошқаруви қарорларининг бажарилишини ташкил этади;"},{"y": "para","x": "- харажатлар сметасини тасдиқлайди;"},{"y": "para","x": "- штатлар жадвалини тасдиқлайди;"},{"y": "para","x": "- бирлашма Бошқарувининг йиғилишларига раислик қилади;"},{"y": "para","x": "-ўз ўринбосарлари ва бошқа ходимларни лавозимга тайинлайди ва лавозимидан озод этади, улар билан меҳнат шартномалари тузади  ва бекор қилади;"},{"y": "para","x": "- белгиланган тартибда Бирлашманинг Бош филиал ва филиаллар ҳамда таркибий тузилмалари раҳбарлари ҳамда уларнинг ўринбосарларини лавозимига тайинлайди ва лавозимидан озод этади;"},{"y": "para","x": "- бирлашманинг ҳудудий таркибий тузилмалари томонидан қабул қилинган амалдаги қонунлар ва Бирлашма Уставига зид келадиган қарор ва буйруқларини бекор қилади;"},{"y": "para","x": "- ўз ўринбосарлари ва бошқа ходимларнинг вазифа доирасини белгилайди, зарур ҳолларда Бирлашма номидан вакил сифатида иш юритиш учун уларга ишончномалар бериш масаласини мустақил ҳал этади;"},{"y": "para","x": "- ишонч қоғозисиз Бирлашма номидан иш кўради ва унинг номидан юридик ва жисмоний шахслар ҳамда халқаро ташкилотлар билан шартнома ва бошқа битимлар тузади,  тааллуқли ходимларга ишончномалар беради;"},{"y": "para","x": "- Бирлашмага қарашли ҳудудий ва бошқа таркибий тузилмаларнинг молиявий-хўжалик фаолиятини текшириш ва тафтиш ўтказишни белгилайди;"},{"y": "para","x": "- Бирлашма ходимлари бажариши мажбурий бўлган буйруқ ва фармойишларни имзолайди;"},{"y": "para","x": "- Бирлашма қошида ташкил этилаётган ташкилотлар ва таркибий тузилмалар ҳақидаги таъсис ҳужжатларини, ички меҳнат тартиби қоидалари ва Бирлашма фаолиятининг бошқа муҳим ҳужжатларини имзолайди;"},{"y": "para","x": "- Бирлашманинг Умумий йиғилишида тасдиқланиши учун янги Бошқарувнинг аъзолигига номзодларни тавсия этади;"},{"y": "para","x": "- Ўзбекистон Республикасининг амалдаги  қонунлари ва мазкур Уставга мувофиқ бошқа масалаларни ҳал қилади."},{"y": "para","x": "Бирлашма Раиси бўлмаган вақтда унинг вазифасини тегишли буйруқ асосида унинг ўринбосарларидан бири вақтинча бажаради."},{"y": "para","x": "Бирлашма раиси лавозимидан озод қилиниши, вафоти, ишдан четлаштирилганлиги муносабати билан ёки бошқа сабабларга кўра, лавозимидан озод қилиш Бошқарув қарори билан унинг вазифасини раис ўринбосарларидан бирини вақтинча  бажарувчи этиб тайинланиши мумкин."},{"y": "para","x": "8. БИРЛАШМАНИНГ  ХУДУДИЙ  БЎЛИНМАЛАРИ"},{"y": "para","x": "8.1. Бирлашманинг бўлинмасига унинг ҳудудий Бош филиал ва филиаллари киради."},{"y": "para","x": "8.2. Юридик шахс мақомига эга бўлган Бош филиал ва филиаллари ҳудудий адлия органларида ҳисобга қўйилиши лозим."},{"y": "para","x": "8.3. Бош филиал ва филиаллар қонун ҳужжатларига мувофиқ тегишли ҳудудда Бирлашманинг мақсад ва вазифаларини амалга оширади."},{"y": "para","x": "8.4. Бош филиал ва филиаллари қонун ҳужжатларига риоя қилиш, Бирлашманинг раҳбар органлари қарорларини бажариш ва бошқа мажбуриятларга эга бўлади."},{"y": "para","x": "8.5. Бош филиал ва филиалларни ташкил қилиш, қайта ташкил қилиш ва тугатиш тартиби, уларнинг ҳуқуқ ва мажбуриятлари, мол-мулкни бошқариш борасидаги ҳуқуқлари, уларнинг раҳбар органлари бўйича батафсил қоидалари Бирлашманинг Низомида белгиланади."},{"y": "para","x": "9. ТАФТИШ   КОМИССИЯСИ."},{"y": "para","x": "9.1.Тафтиш комиссияси Бирлашма Умумий йиғилишида Бирлашма  аъзолари орасидан уч нафари таркибида сайланади ва Бошқарувга ҳисобот беради."},{"y": "para","x": "Тафтиш комиссияси ўз фаолиятида мазкур Устав ва Бирлашма Умумий йиғилиши томонидан тасдиқланган «Ўзбекистон Халқаро Арбитраж Судлари  Бирлашмасининг Тафтиш комиссияси тўғрисида»ги Низомига амал қилади."},{"y": "para","x": "9.2.Тафтиш комиссиясига сайланган аъзолар Бирлашма Бошқаруви таркибига киритилиши мумкин эмас, шунингдек Бирлашманинг молия-хўжалик фаолияти учун жавобгар шахслар ҳам Тафтиш комиссияси аъзоси бўлиши мумкин эмас."},{"y": "para","x": "10. БИРЛАШМА  УСТАВИГА  ЎЗГАРТИРИШ  ВА  ҚЎШИМЧАЛАР КИРИТИШ  ТАРТИБИ"},{"y": "para","x": "10.1. Бирлашманинг Уставига ўзгартириш ва қўшимчалар киритиш Бошқарув қарорига асосан амалга оширилади. Уставга ўзгартириш  ва қўшимчалар киритилгандан сўнг, Бирлашма қайта рўйхатдан ўтказилиши лозим."},{"y": "para","x": "Уставга киритилган ўзгартириш ва қўшимчалар Бирлашма қайта рўйхатдан ўтгандан сўнг қонуний кучга эга бўлади."},{"y": "para","x": "11. БИРЛАШМА  ФАОЛИЯТИНИ  ТЎХТАТИБ  ҚЎЙИШ"},{"y": "para","x": "11.1. Бирлашманинг фаолияти Ўзбекистон Республикаси Конституцияси ва бошқа қонун ҳужжатлари бузилган тақдирда ваколатли суд томонидан тўхтатиб қўйилади."},{"y": "para","x": "12. БИРЛАШМА  ФАОЛИЯТИНИ  ҚАЙТА  ТАШКИЛ  ЭТИШ  ВА ТУГАТИШ  ТАРТИБИ"},{"y": "para","x": "12.1. Бирлашма фаолиятини тугатиш суд қарори ёки Умумий йиғилиш қарори билан амалга оширилиши мумкин. Бирлашма фаолиятини тугатиш тўғрисидаги қарор қабул қилган орган давлат рўйхатидан ўтказувчи Адлия органи билан келишган холда тугатиш Комиссиясини тайинлайди."},{"y": "para","x": "12.2. Бирлашмани қайта ташкил қилиш Умумий йиғилиш қарори асосида Ўзбекистон Республикасининг Қонун ҳужжатларига кўра амалга оширилади."},{"y": "para","x": "12.3. Бирлашма Умумий йиғилишнинг қарори асосида қайта тузилганда Бирлашма мулки унинг ҳуқуқий ворисига ўтказилади, суд қарорига асосан тугатилганда эса аъзолар ўртасида бўлинмайди ва Умумий йиғилиш қарори асосида Уставда белгиланган вазифаларни амалга ошириш учун йўналтирилади."},{"y": "para","x": "12.4. Устав қоидаларини Ўзбекистон Республикаси норматив-ҳуқуқий ҳужжатларига зид тарзда талқин қилиш мумкин эмас ҳамда Устав қоидаларининг Ўзбекистон Республикаси норматив-ҳуқуқий ҳужжатларига зид тарзда ифода қилинган бандлари ҳақиқий эмасдир."},{"y": "para","x": "Ушбу Устав хужжати жами"},{"y": "para","x": "13  (ўн уч)   вароқда   ип    билан"},{"y": "para","x": "шнурланиб   тикилди,  бетланди"},{"y": "para","x": "ва    сургучланиб   имзоланди."},{"y": "para","x": "______________Н.Т.Тоғаев"},{"y": "para","x": "14"}]};
